def mix(c1, c2, t):
    t = max(0.0, min(1.0, t))
    a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
    return "#%02x%02x%02x" % tuple(round(a[i] + (b[i] - a[i]) * t) for i in range(3))


def runs(rows):
    """Merge lit pixels of a bitmap into horizontal runs: [(row, col_start, col_end_exclusive)]."""
    out = []
    for r, row in enumerate(rows):
        c = 0
        while c < len(row):
            if row[c] == "#":
                s = c
                while c < len(row) and row[c] == "#":
                    c += 1
                out.append((r, s, c))
            else:
                c += 1
    return out


def text_rows(text):
    """Bitmap rows (7 strings) for a string in the 5x7 pixel font, 1px letter gap."""
    rows = [""] * 7
    for ch in text.upper():
        g = GLYPHS.get(ch, GLYPHS[" "])
        for i in range(7):
            rows[i] += g[i] + "."
    return [r[:-1] for r in rows]


def draw_bitmap(cv, rows, x, y, px, color, tags=()):
    for r, c0, c1 in runs(rows):
        cv.create_rectangle(x + c0 * px, y + r * px, x + c1 * px, y + (r + 1) * px, fill=color, outline="", tags=tags)


# ------------------------------------------------- pure geometry (previewable)
TITLE = "NETSCOUT"
STAGE_W, STAGE_H = 360, 330
CX, CY = STAGE_W // 2, STAGE_H // 2 - 2
BANNER_W = 104                       # target pixel width of the fire text
FIRE_FONTS = ("Impact", "Haettenschweiler", "Arial Black", "Georgia", "DejaVu Sans")
OUTLINE_COLOR = "#8a1000"            # dark ember red: visible against the black background
OUTLINE_OFFS = [(-2, -2), (0, -2), (2, -2), (-2, 0), (2, 0), (-2, 2), (0, 2), (2, 2)]
GLOW_STEPS = 12
EMBER_STOPS = [(1.0, "#fff3a0"), (0.7, "#ffb000"), (0.45, "#ff5a00"), (0.2, "#b01000"), (0.0, "#200000")]


def snap(v, g):
    return int(round(v / g) * g)


def ring_pts(cx, cy, r, step, g=3):
    n = max(8, int(2 * math.pi * r / step))
    pts = {(snap(cx + r * math.cos(2 * math.pi * i / n), g), snap(cy + r * math.sin(2 * math.pi * i / n), g))
           for i in range(n)}
    return sorted(pts)


def arc_pts(cx, cy, r, a0, a1, step, g=3):
    n = max(2, int(math.radians(a1 - a0) * r / step))
    pts = {(snap(cx + r * math.cos(math.radians(a0 + (a1 - a0) * i / n)), g),
            snap(cy + r * math.sin(math.radians(a0 + (a1 - a0) * i / n)), g)) for i in range(n + 1)}
    return sorted(pts)


def ray_pts(angle, r0, r1, step, cx=CX, cy=CY, g=3):
    rad = math.radians(angle)
    return [(snap(cx + r * math.cos(rad), g), snap(cy + r * math.sin(rad), g)) for r in range(r0, r1, step)]


def banner_positions(angle, rx, ry, n=2, cx=CX, cy=CY):
    """Centres of the fire banners. The text itself is never rotated, so NETSCOUT always reads left to right."""
    return [(cx + rx * math.cos(math.radians(angle + i * 360.0 / n)),
             cy + ry * math.sin(math.radians(angle + i * 360.0 / n))) for i in range(n)]


def ember_color(life):
    life = max(0.0, min(1.0, life))
    for (l1, c1), (l0, c0) in zip(EMBER_STOPS, EMBER_STOPS[1:]):
        if life >= l0:
            return mix(c0, c1, (life - l0) / (l1 - l0))
    return EMBER_STOPS[-1][1]


def glow_color(i, pulse=1.0):
    """i = 0 is the outermost ring of the ember glow, GLOW_STEPS-1 the innermost."""
    t = (i + 1) / GLOW_STEPS
    return mix(BG, "#7a1200", min(1.0, (t ** 1.6) * pulse))


# --------------------------------------------------------------- widgets
_FONTS = {}


def text_px(text, size, bold=True, family=None):
    """Real rendered width of `text` in pixels, measured with Tk's own font metrics. Widgets are only
    ever built once a Tk root exists, so the measurement is normally exact; if it can't be taken for
    any reason, a deliberately generous estimate is used instead so nothing is ever sized too small."""
    fam = family or UIFONT
    key = (fam, size, bold)
    f = _FONTS.get(key)
    if f is None:
        try:
            from tkinter import font as tkfont
            f = tkfont.Font(family=fam, size=size, weight="bold" if bold else "normal")
            _FONTS[key] = f
        except Exception:
            f = None
    if f is not None:
        try:
            return int(f.measure(text))
        except Exception:
            pass
    return int(len(text) * size * (0.80 if bold else 0.72)) + 2


def btn_w(text, size=10, pad=None):
    """Width a flat button needs for its own label: the measured text plus fixed side padding (16px a
    side, as in the mockup) - sized from the text, so no button carries dead space."""
    return text_px(text, size) + (BTN_PAD if pad is None else pad)


def windows_crisp_text():
    """On a scaled Windows display (125%, 150% - the default on most laptops) a program that doesn't
    declare DPI awareness is drawn at 100% and then stretched by Windows as a bitmap, so every letter
    comes out soft and blocky. Asking for GDI scaling instead makes Windows re-draw the text and shapes
    Tk paints at the screen's real resolution, while the layout stays exactly as designed. Needs
    Windows 10 1809 or later; on anything older, or if the call fails, nothing changes."""
    if ns.OS != "Windows":
        return
    try:
        import ctypes
        ctypes.windll.user32.SetProcessDpiAwarenessContext(ctypes.c_void_p(-5))
    except Exception:
        pass


class DetailLabel(tk.Label):
    """The DETAIL line under a table (the mockup's red-edged callout). Its callout hides itself while
    there is nothing to say and comes back the moment there is, so an empty box never sits there."""

    box = None

    def configure(self, cnf=None, **kw):
        r = super().configure(cnf, **kw) if cnf else super().configure(**kw)
        if "text" in kw and self.box is not None:
            try:
                (self.box.grid if kw["text"] else self.box.grid_remove)()
            except Exception:
                pass
        return r

    config = configure


ACRONYMS = {"WIFI": "WiFi", "MAC": "MAC", "DHCP": "DHCP", "IP": "IP", "IPV6": "IPv6"}


def pretty_tool(label):
    """'DEVICE SCAN' -> 'Device scan', 'WIFI AUDIT' -> 'WiFi audit' - the sentence case the mockup's
    footer and mascot caption use ('Device scan complete - 6.4s'), acronyms kept intact."""
    words = label.split()
    out = [ACRONYMS.get(w, w.lower()) for w in words]
    if out and words and out[0] == words[0].lower():
        out[0] = out[0][:1].upper() + out[0][1:]
    return " ".join(out)


class PixelButton(tk.Canvas):
    """Flat button from the RedPro mockup (the class name is historical - nothing here is pixel art any
    more): a rounded panel with a hairline border and real anti-aliased text. `solid` = the red primary
    action; `selected` = a chip/toggle that is on. `bg` is the colour of whatever the button sits on, so
    its rounded corners blend into it. Small chips (28px and under) are drawn as pills."""

    def __init__(self, master, text, width=310, height=54, icon=None, px=3, command=None, toggle=False,
                 selected=False, solid=False, center=False, bg=None, size=None):
        self.surface = bg or BG
        super().__init__(master, width=width, height=height, bg=self.surface, highlightthickness=0, bd=0,
                         cursor="hand2")
        self.W, self.H, self.text, self.icon, self.px = width, height, text, icon, px
        self.size = size or (10 if height >= 34 else 9)
        self.command, self.toggle, self.solid, self.center = command, toggle, solid, center
        self.selected, self.hover, self.disabled, self._down = selected, False, False, False
        self.bind("<Enter>", lambda e: self._set_hover(True))
        self.bind("<Leave>", lambda e: self._set_hover(False))
        self.bind("<ButtonPress-1>", self._press)
        self.bind("<ButtonRelease-1>", self._release)
        self.render()

    def _set_hover(self, v):
        if not self.disabled:
            self.hover = v
            self.render()

    def _press(self, _e):
        if not self.disabled:
            self._down = True

    def _release(self, e):
        if self.disabled or not self._down:
            return
        self._down = False
        if 0 <= e.x <= self.W and 0 <= e.y <= self.H:
            if self.toggle:
                self.selected = not self.selected
                self.render()
            if self.command:
                self.command()

    def set_text(self, text):
        """Relabel after creation - render() reads self.text each time, so a redraw is all it takes."""
        self.text = text
        self.render()

    def set_selected(self, v):
        self.selected = v
        self.render()

    def set_disabled(self, v):
        self.disabled = v
        self.hover = False
        self.configure(cursor="arrow" if v else "hand2")
        self.render()

    def _round_rect(self, x0, y0, x1, y1, r, **kw):
        r = max(1, min(r, (x1 - x0) // 2, (y1 - y0) // 2))
        pts = [x0 + r, y0, x1 - r, y0, x1, y0, x1, y0 + r, x1, y1 - r, x1, y1,
               x1 - r, y1, x0 + r, y1, x0, y1, x0, y1 - r, x0, y0 + r, x0, y0]
        return self.create_polygon(pts, smooth=True, **kw)

    def render(self):
        self.delete("all")
        w, h = self.W, self.H
        on = self.selected or self.solid
        if self.disabled:
            fill, border, fg = self.surface, "#1E2128", "#4A4F59"
            if self.solid:
                fill, border, fg = "#3A1A20", "#3A1A20", "#9A7A80"
        elif on:
            fill = "#F43A50" if self.hover else RED
            border, fg = fill, WHITE
        else:
            fill = "#16191F" if self.hover else self.surface
            border = "#3A404A" if self.hover else LINE2
            fg = WHITE if self.hover else "#C7CBD2"
        r = h // 2 if h <= 28 else 7
        self._round_rect(0, 0, w - 1, h - 1, r, fill=fill, outline=border, width=1)
        font = (UIFONT, self.size, "bold")
        if self.icon and not self.center:
            cy = h // 2
            self.create_oval(12, cy - 3, 18, cy + 3, fill=(RED if on else DIM), outline="")
            self.create_text(28, cy, text=self.text, fill=fg, font=font, anchor="w")
        else:
            self.create_text(w // 2 if self.center else 14, h // 2, text=self.text, fill=fg, font=font,
                             anchor="center" if self.center else "w")


class SideButton(PixelButton):
    """A tool in the left sidebar, drawn like the mockup: no box at rest; the active tool gets a lifted
    panel, a red bar down its left edge and a red dot. A red pill on the right counts alerts that tool
    has raised which nobody has looked at yet (THREAT MONITOR's '2' in the mockup)."""

    def __init__(self, master, text, width=214, height=36, command=None, selected=False):
        self.badge = 0
        super().__init__(master, text, width=width, height=height, icon="dot", px=2, command=command,
                         selected=selected, bg=SIDE_BG, size=10)

    def set_badge(self, n):
        n = max(0, int(n or 0))
        if n != self.badge:
            self.badge = n
            self.render()

    def render(self):
        self.delete("all")
        w, h = self.W, self.H
        cy = h // 2
        if self.selected:
            self._round_rect(0, 0, w - 1, h - 1, 7, fill="#1C1F26", outline="")
            self.create_rectangle(0, 5, 2, h - 5, fill=RED, outline="")
            dot, fg, weight = RED, TEXT, "bold"
        elif self.hover:
            self._round_rect(0, 0, w - 1, h - 1, 7, fill="#16191F", outline="")
            dot, fg, weight = SUB, TEXT, "normal"
        else:
            dot, fg, weight = DIM, SOFT, "normal"
        self.create_oval(10, cy - 3, 16, cy + 3, fill=dot, outline="")
        self.create_text(26, cy, text=self.text, fill=fg, font=(UIFONT, 10, weight), anchor="w")
        if self.badge:
            t = str(self.badge) if self.badge < 100 else "99+"
            bw = max(18, text_px(t, 8) + 12)
            self._round_rect(w - 8 - bw, cy - 8, w - 8, cy + 8, 8, fill=RED, outline="")
            self.create_text(w - 8 - bw // 2, cy, text=t, fill=WHITE, font=(UIFONT, 8, "bold"))


class TabChip(PixelButton):
    """A browser-style tab in the strip under the top bar: plain text, the active one bright with a red
    underline (the mockup's DEVICE SCAN tab). A red dot while its tool runs, a red pill counting unseen
    alerts (or '!' for a run that finished while you were elsewhere), and a quiet x to close it."""

    CLOSE = 24

    def __init__(self, master, text, command=None, on_close=None, selected=False, running=False, badge=""):
        self.running, self.badge, self.on_close = running, str(badge or ""), on_close
        width = 16 + text_px(text, 10) + (14 if running else 0) + (self._badge_w() + 8 if self.badge else 0) \
            + self.CLOSE + 6
        super().__init__(master, text, width=width, height=44, px=2, command=command, selected=selected,
                         center=True, bg=BAR_BG, size=10)

    def _badge_w(self):
        return max(18, text_px(self.badge, 8) + 12)

    def _release(self, e):
        if self.disabled or not self._down:
            return
        self._down = False
        if not (0 <= e.x <= self.W and 0 <= e.y <= self.H):
            return
        if self.on_close and e.x >= self.W - self.CLOSE - 4:
            self.on_close()
        elif self.command:
            self.command()

    def render(self):
        self.delete("all")
        w, h = self.W, self.H
        cy = h // 2
        fg = TEXT if self.selected else ("#C7CBD2" if self.hover else MUTED)
        x = 16
        self.create_text(x, cy, text=self.text, fill=fg, font=(UIFONT, 10, "bold"), anchor="w")
        x += text_px(self.text, 10) + 8
        if self.running:
            self.create_oval(x, cy - 3, x + 6, cy + 3, fill=RED, outline="")
            x += 14
        if self.badge:
            bw = self._badge_w()
            self._round_rect(x, cy - 8, x + bw, cy + 8, 8, fill=RED, outline="")
            self.create_text(x + bw // 2, cy, text=self.badge, fill=WHITE, font=(UIFONT, 8, "bold"))
        self.create_text(w - self.CLOSE // 2 - 4, cy, text="×", fill=(RED if self.hover else SUB),
                         font=(UIFONT, 12))
        if self.selected:
            self.create_rectangle(0, h - 2, w, h, fill=RED, outline="")


class Segmented(tk.Canvas):
    """The mockup's joined toggle group (All | At risk | High): one bordered pill with the chosen
    segment filled red. Exactly one segment is ever selected. Carries W/H/text/px like a PixelButton so
    the action bar can lay it out in the same reflowing row."""

    def __init__(self, master, options, command=None, selected=None, height=40, bg=None, size=9):
        self.surface = bg or BG
        self.options = list(options)
        self.size = size
        self.widths = [btn_w(lbl, size) for _, lbl in self.options]
        self.W, self.H, self.px = sum(self.widths), height, 2
        self.text = " | ".join(lbl for _, lbl in self.options)
        super().__init__(master, width=self.W, height=self.H, bg=self.surface, highlightthickness=0, bd=0,
                         cursor="hand2")
        self.command = command
        self.selected = selected or self.options[0][0]
        self.hover_i, self.disabled = None, False
        self.bind("<Motion>", lambda e: self._hover(self._index_at(e.x)))
        self.bind("<Leave>", lambda e: self._hover(None))
        self.bind("<ButtonRelease-1>", self._click)
        self.render()

    def _index_at(self, x):
        acc = 0
        for i, wd in enumerate(self.widths):
            if acc <= x < acc + wd:
                return i
            acc += wd
        return None

    def _hover(self, i):
        if not self.disabled and i != self.hover_i:
            self.hover_i = i
            self.render()

    def _click(self, e):
        i = self._index_at(e.x)
        if self.disabled or i is None or not (0 <= e.y <= self.H):
            return
        self.pick(self.options[i][0])
        if self.command:
            self.command(self.selected)

    def pick(self, key):
        self.selected = key
        self.render()

    def set_disabled(self, v):
        self.disabled = bool(v)
        self.hover_i = None
        self.configure(cursor="arrow" if v else "hand2")
        self.render()

    _round_rect = PixelButton._round_rect

    def render(self):
        self.delete("all")
        w, h = self.W, self.H
        self._round_rect(0, 0, w - 1, h - 1, 7, fill=self.surface, outline=LINE2, width=1)
        x = 0
        for i, ((key, lbl), wd) in enumerate(zip(self.options, self.widths)):
            sel = key == self.selected
            if sel or (self.hover_i == i and not self.disabled):
                col = ("#5A2630" if self.disabled else RED) if sel else "#16191F"
                x0, x1 = x + (1 if i == 0 else 0), x + wd - (2 if i == len(self.options) - 1 else 0)
                self._round_rect(x0, 1, x1, h - 2, 6, fill=col, outline="")
                # square off the inner corners so the fill butts cleanly against its neighbours
                if i > 0:
                    self.create_rectangle(x0, 1, x0 + 7, h - 2, fill=col, outline="")
                if i < len(self.options) - 1:
                    self.create_rectangle(x1 - 7, 1, x1, h - 2, fill=col, outline="")
            fg = "#4A4F59" if self.disabled and not sel else (WHITE if sel else SOFT)
            self.create_text(x + wd // 2, h // 2, text=lbl, fill=fg, font=(UIFONT, self.size, "bold"))
            x += wd


class Tile(tk.Canvas):
    """One stat tile from the mockup (DEVICES 6 / AT RISK 2 / NEW 1 / SCAN TIME 6.4s): a rounded panel,
    a small caps title, a big value. The value is a real Label (so it can wrap, and so the rest of the
    app reads and sets it like any label); the panel and the optional red accent bar are drawn on the
    canvas behind it and redrawn whenever the tile is resized."""

    H = 76

    def __init__(self, master, title, value="—", unit="", accent=False, mono=False):
        super().__init__(master, height=self.H, width=150, bg=BG, highlightthickness=0, bd=0)
        self.title, self.accent, self.mono, self._cw = title, accent, mono, 150
        self.inner = tk.Frame(self, bg=PANEL)
        vfont = (FONT, 10, "bold") if mono else (UIFONT, 20, "bold")
        self.value = tk.Label(self.inner, text=value, bg=PANEL, fg=(PINK if accent else TEXT), font=vfont,
                              anchor="w", justify="left", bd=0, padx=0, pady=0)
        self.value.pack(side="left", anchor="s")
        self.unit = tk.Label(self.inner, text=unit, bg=PANEL, fg=MUTED, font=(UIFONT, 11, "bold"), bd=0,
                             padx=2, pady=0)
        self.unit.pack(side="left", anchor="s", pady=(0, 3))
        self._win = self.create_window(16, 30 if not mono else 32, window=self.inner, anchor="nw")
        self.bind("<Configure>", lambda e: self.draw(e.width))
        self.draw(self._cw)

    _round_rect = PixelButton._round_rect

    def draw(self, w):
        if not w or w < 20:
            return
        self._cw = w
        self.delete("bg")
        self._round_rect(0, 0, w - 1, self.H - 1, 9, fill=PANEL, outline=LINE, width=1, tags="bg")
        if self.accent:
            self.create_rectangle(0, 10, 3, self.H - 10, fill=RED, outline="", tags="bg")
        self.create_text(16, getattr(self, "_title_y", 19), text=self.title, fill=MUTED, font=(UIFONT, 8, "bold"),
                         anchor="w", tags="bg")
        try:
            self.tag_lower("bg")
        except Exception:
            pass
        if self.mono:
            self.value.configure(wraplength=max(40, w - 32))

    def set_compact(self, compact):
        """Short-window variant: a slimmer tile with a smaller number, so a 768px screen keeps table rows."""
        self.H = 58 if compact else 76
        try:
            self.configure(height=self.H)
            if not self.mono:
                self.value.configure(font=(UIFONT, 15 if compact else 20, "bold"))
            self.coords(self._win, 16, (24 if compact else 30) if not self.mono else (26 if compact else 32))
            self._title_y = 15 if compact else 19
            self.draw(self._cw)
        except Exception:
            pass

    def set(self, value, unit="", accent=None, title=None):
        if title is not None and title != self.title:
            self.title = title
            self.draw(self._cw)
        if accent is not None and bool(accent) != self.accent:
            self.accent = bool(accent)
            self.draw(self._cw)
        self.value.configure(text=value, fg=(PINK if self.accent else TEXT))
        self.unit.configure(text=unit)


REAPER_W, REAPER_MIN_H = 320, 470

# How the reaper MOVES for each kind of tool. Every value drives the mascot's OWN layers - the scythe
# (art exists only for -4deg..+5deg), the free bony arm (-3deg..+3deg), the eye-ember frames (0..7) and the
# float/head offsets - so the motion always stays in the reaper's own style; nothing foreign is ever drawn.
# A tool only changes the SPEED, REACH and INTENSITY of those parts, giving each its own personality:
#   float_per  - how slowly the whole figure rises and settles (s)
#   sway_per   - the scythe's sway period (s); sway_lo/sway_hi - its reach, clamped to the art's -4..+5
#   arm_amp/arm_per (+ a smaller arm_amp2/arm_per2 wobble) - the free arm's swing, clamped to -3..+3
#   eye_per/eye_lo/eye_top - the eye embers' pulse: faster + a higher floor = hotter, more awake
#   look_choices + look_min/look_max - how far and how often the head glances aside (frames at 40ms)
ANIM_IDLE = dict(float_per=5.5, sway_per=4.0, sway_lo=-4.0, sway_hi=5.0, arm_amp=2.4, arm_per=6.3,
                 arm_amp2=0.6, arm_per2=2.1, eye_per=2.2, eye_lo=0, eye_top=7,
                 look_choices=(-3.0, 0.0, 0.0, 3.0), look_min=35, look_max=110)
ANIM_PROFILES = {
    # predatory: fast hot eyes, quick darting glances, a brisk full-reach sway - "on the hunt"
    "hunt": dict(float_per=4.0, sway_per=1.6, sway_lo=-4.0, sway_hi=5.0, arm_amp=2.5, arm_per=5.0,
                 arm_amp2=0.5, arm_per2=1.7, eye_per=0.8, eye_lo=4, eye_top=7,
                 look_choices=(-3.0, 3.0, -3.0, 3.0, 0.0), look_min=10, look_max=28),
    # methodical scanning: the scythe sweeps its whole arc, steady medium eyes, slow deliberate glances
    "sweep": dict(float_per=5.0, sway_per=2.6, sway_lo=-4.0, sway_hi=5.0, arm_amp=2.2, arm_per=6.0,
                  arm_amp2=0.5, arm_per2=2.3, eye_per=1.5, eye_lo=2, eye_top=6,
                  look_choices=(-3.0, 0.0, 3.0), look_min=24, look_max=60),
    # enforcement / power: scythe raised and tense (top of its arc, short sharp sway), hottest steady
    # eyes, the free hand busiest - the reaper about to strike
    "strike": dict(float_per=4.6, sway_per=1.4, sway_lo=2.0, sway_hi=5.0, arm_amp=2.6, arm_per=3.8,
                   arm_amp2=0.4, arm_per2=1.3, eye_per=1.0, eye_lo=5, eye_top=7,
                   look_choices=(-2.0, 2.0, 0.0), look_min=14, look_max=30),
    # inquisitive lookup: quick small glances, medium-bright eyes, a light gentle sway
    "signal": dict(float_per=4.8, sway_per=2.2, sway_lo=-3.0, sway_hi=4.0, arm_amp=2.0, arm_per=5.2,
                   arm_amp2=0.5, arm_per2=2.0, eye_per=1.3, eye_lo=1, eye_top=7,
                   look_choices=(-3.0, 3.0, 0.0, 0.0), look_min=18, look_max=40),
    # steady vigilance: a touch livelier than idle but calm and watchful
    "watch": dict(float_per=5.2, sway_per=3.2, sway_lo=-4.0, sway_hi=4.0, arm_amp=2.2, arm_per=6.0,
                  arm_amp2=0.5, arm_per2=2.1, eye_per=1.8, eye_lo=1, eye_top=7,
                  look_choices=(-3.0, 0.0, 3.0, 0.0), look_min=28, look_max=80),
}
# which personality each tool wears (anything unlisted falls back to a lively "sweep")
TOOL_ANIM = {
    "threats": "hunt", "packet": "hunt", "vuln": "hunt", "audit": "hunt", "wifisec": "hunt",
    "scan": "sweep", "nets": "sweep", "ports": "sweep", "server": "sweep", "apscan": "sweep",
    "topo": "sweep", "survey": "sweep", "spectrum": "sweep", "ifaces": "sweep", "router": "sweep",
    "cable": "sweep", "switch": "sweep",
    "power": "strike", "policy": "strike", "saver": "strike", "firewall": "strike",
    "dhcp": "strike", "macpriv": "strike",
    "dns": "signal", "web": "signal", "subnet": "signal", "wifi": "signal", "bt": "signal",
    "live": "watch", "monitor": "watch", "ping": "watch", "info": "watch", "camera": "watch",
    "report": "watch", "health": "watch", "actionlog": "watch",
}


class SkullStage(tk.Canvas):
    """The mascot panel on the right: the RedPro mockup's grim reaper, assembled from layers rendered
    straight from that mockup's own SVG (REAPER, below) and animated the same way - the scythe sways
    -4..+5 degrees about the gripping hand, the whole figure floats, the eyes pulse one after the other -
    plus a head that bobs and now and then glances aside, and a bony arm that swings. It never stops,
    tool or no tool; a running tool just makes it livelier (faster sway, hotter eyes) and the caption
    says what it is doing. The class keeps its old name so everything that builds and drives it is
    unchanged; `frames` (the retired pixel skull) is accepted and ignored. All drawing is guarded - a
    quirky Tk must never turn a cosmetic animation into a crash."""

    SWAY = (-4.0, 5.0)

    def __init__(self, master, frames=None):
        super().__init__(master, width=REAPER_W, height=REAPER_MIN_H, bg=BG, highlightthickness=0, bd=0)
        self.t, self.mode, self.images = 0, None, []
        self.W, self.H = REAPER_W, REAPER_MIN_H
        self.fx = self.fy = 0
        self.head_dx = self.head_dy = 0.0
        self.look, self.look_t = 0.0, 40
        self.t0 = time.monotonic()
        self.ids, self.pics = {}, {}
        try:
            self._load()
            self._build()
        except Exception:
            pass
        self.bind("<Configure>", self._on_resize)
        self.after(40, self._tick)

    # --- assets -----------------------------------------------------------
    def _load(self):
        def img(d):
            p = tk.PhotoImage(data=d["png"])
            self.images.append(p)          # Tk drops an image nobody holds a reference to
            return p
        for k in ("shadow", "robe", "skull", "glove"):
            self.pics[k] = img(REAPER[k])
        for k in ("scythe", "arm", "eyeL", "eyeR"):
            self.pics[k] = [img(f) for f in REAPER[k]]

    # --- scene ------------------------------------------------------------
    def _origin(self):
        block = REAPER["fig_h"] + 70                     # figure + caption underneath it
        self.fx = (self.W - REAPER["fig_w"]) // 2
        self.fy = max(16, (self.H - block) // 2 + 6)

    def _backdrop(self):
        """The mockup's panel background, in vector so it fits any panel size with no seams: a dark
        red-black radial wash centred on the figure, plus a soft red glow behind the head and chest."""
        W, H = self.W, self.H
        cx, cy = W / 2, self.fy + 110
        rx, ry = max(230, 0.72 * W), max(250, 0.36 * H)
        steps = 34
        for k in range(steps, 0, -1):
            t = k / steps
            self.create_oval(cx - rx * t, cy - ry * t, cx + rx * t, cy + ry * t,
                             fill=mix("#1A0E12", BG, t), outline="", tags="bg")
        gx, gy, gr = W / 2, self.fy + 150, 92
        base = mix("#1A0E12", BG, 0.25)
        for k in range(18, 0, -1):
            t = k / 18
            self.create_oval(gx - gr * t, gy - gr * t, gx + gr * t, gy + gr * t,
                             fill=mix(base, RED, 0.22 * (1 - t)), outline="", tags="bg")

    def _build(self):
        self.delete("all")
        self._origin()
        self._backdrop()
        R, P = REAPER, self.pics
        self.ids["shadow"] = self.create_image(self.fx + R["shadow"]["x"], self.fy + R["shadow"]["y"],
                                               image=P["shadow"], anchor="nw")
        for k in ("robe", "skull"):
            self.ids[k] = self.create_image(0, 0, image=P[k], anchor="nw")
        self.ids["eyeL"] = self.create_image(0, 0, image=P["eyeL"][0], anchor="nw")
        self.ids["eyeR"] = self.create_image(0, 0, image=P["eyeR"][0], anchor="nw")
        self.ids["arm"] = self.create_image(0, 0, image=P["arm"][len(P["arm"]) // 2], anchor="nw")
        self.ids["scythe"] = self.create_image(0, 0, image=P["scythe"][0], anchor="nw")
        self.ids["glove"] = self.create_image(0, 0, image=P["glove"], anchor="nw")
        title, sub = self.caption()
        self.ids["title"] = self.create_text(self.W // 2, self.fy + R["fig_h"] + 26, text=title, fill=TEXT,
                                             font=(UIFONT, 11, "bold"))
        self.ids["sub"] = self.create_text(self.W // 2, self.fy + R["fig_h"] + 48, text=sub, fill=MUTED,
                                           font=(UIFONT, 9))
        self._frame()

    def _on_resize(self, e):
        if e.width < 40 or e.height < 40 or (e.width, e.height) == (self.W, self.H):
            return
        self.W, self.H = e.width, e.height
        try:
            self._build()
        except Exception:
            pass

    def caption(self):
        if self.mode is None:
            return "Watching your network", "Defensive mode · idle"
        label = next((l for k, l, _ in TOOLS if k == self.mode), str(self.mode).upper())
        title = {"threats": "Hunting for threats", "monitor": "Standing watch",
                 "live": "Watching live"}.get(self.mode, f"{pretty_tool(label)} running")
        return title, "Defensive mode · active"

    def set_mode(self, mode):
        self.mode = mode
        try:
            title, sub = self.caption()
            if "title" in self.ids:
                self.itemconfigure(self.ids["title"], text=title)
                self.itemconfigure(self.ids["sub"], text=sub)
        except Exception:
            pass

    # --- animation --------------------------------------------------------
    def _profile(self):
        """The motion personality for the current tool - how the reaper's own parts move right now. Idle
        when no tool is running; otherwise the tool's profile, falling back to a lively 'sweep'."""
        if self.mode is None:
            return ANIM_IDLE
        return ANIM_PROFILES.get(TOOL_ANIM.get(self.mode, "sweep"), ANIM_PROFILES["sweep"])

    def _tick(self):
        self._frame()
        self.after(40, self._tick)

    def _frame(self):
        try:
            if not self.ids:
                return
            self.t += 1
            now = time.monotonic() - self.t0
            pr = self._profile()
            R, P = REAPER, self.pics
            cosw = lambda per, ph=0.0: 0.5 - 0.5 * math.cos(2 * math.pi * (now - ph) / per)
            # whole figure floats up to 7px and settles (mockup rp-float) - pace set by the tool
            fl = -7.0 * cosw(pr["float_per"])
            # scythe sways within the art's reach (-4..+5), at the tool's pace and reach
            lo_a = max(-4.0, pr["sway_lo"])
            hi_a = min(5.0, pr["sway_hi"])
            ang = lo_a + (hi_a - lo_a) * cosw(pr["sway_per"])
            sa = R["scythe_angles"]
            si = max(0, min(len(sa) - 1, round((ang - sa[0]) / 0.5)))
            # the free bony arm swings a few degrees (clamped to its -3..+3 art), with a smaller wobble so
            # it is never metronomic - the tool sets how far and how fast
            aa = (pr["arm_amp"] * math.sin(2 * math.pi * now / pr["arm_per"])
                  + pr["arm_amp2"] * math.sin(2 * math.pi * now / pr["arm_per2"]))
            arm_a = R["arm_angles"]
            ai = max(0, min(len(arm_a) - 1, round((aa - arm_a[0]) / 0.5)))
            # head: a slow bob, plus every so often a glance to one side (eased, never a jump); the tool
            # sets how far it looks and how often
            self.look_t -= 1
            if self.look_t <= 0:
                self.look = random.choice(pr["look_choices"])
                self.look_t = random.randint(pr["look_min"], pr["look_max"])
            self.head_dx += (self.look - self.head_dx) * 0.12
            self.head_dy = 1.6 * math.sin(2 * math.pi * now / 3.3)
            # eyes pulse between the tool's floor and ceiling (0..7 frames), the right one .4s behind the
            # left; a faster period with a higher floor reads as hotter, more awake
            per, lo, top = pr["eye_per"], pr["eye_lo"], pr["eye_top"]
            le = lo + round((top - lo) * cosw(per))
            re_ = lo + round((top - lo) * cosw(per, 0.4))
            fx, fy = self.fx, self.fy + round(fl)
            hx, hy = round(self.head_dx), round(self.head_dy)

            def put(name, d, dx=0, dy=0):
                self.coords(self.ids[name], fx + d["x"] + dx, fy + d["y"] + dy)

            put("robe", R["robe"])
            put("skull", R["skull"], hx, hy)
            self.itemconfigure(self.ids["eyeL"], image=P["eyeL"][le])
            put("eyeL", R["eyeL"][le], hx, hy)
            self.itemconfigure(self.ids["eyeR"], image=P["eyeR"][re_])
            put("eyeR", R["eyeR"][re_], hx, hy)
            self.itemconfigure(self.ids["arm"], image=P["arm"][ai])
            put("arm", R["arm"][ai])
            self.itemconfigure(self.ids["scythe"], image=P["scythe"][si])
            put("scythe", R["scythe"][si])
            put("glove", R["glove"])
        except Exception:
            pass


