TOOL_GROUPS = [("RECON", ["scan", "info", "nets", "ports", "router", "topo", "ifaces"]),
               ("SECURITY", ["audit", "server", "vuln", "health", "report"]),
               ("WIRELESS", ["wifisec", "spectrum", "apscan", "survey", "wifi", "bt"]),
               ("MONITOR", ["threats", "monitor", "live", "packet", "actionlog"]),
               ("DEFENSE", ["firewall", "dhcp", "macpriv"]),
               ("DIAGNOSE", ["ping", "switch", "cable"]),
               ("CONTROL", ["power", "policy", "saver", "camera"]),
               ("TOOLKIT", ["subnet", "dns", "web"])]


def tool_groups():
    known = {k for _, keys in TOOL_GROUPS for k in keys}
    out = [(name, [k for k in keys if any(k == t for t, _, _ in TOOLS)]) for name, keys in TOOL_GROUPS]
    extra = [k for k, _, _ in TOOLS if k not in known]
    return out + ([("MORE", extra)] if extra else [])

