def row_tag(d):
    base = {"OFFLINE": "offline", "NO PING": "noping"}.get(d.get("state"))
    if base:
        return base
    # a device that answers but has a HIGH-severity open port (e.g. an unauthenticated database, the
    # Docker API) is worth standing out from the crowd the same way an OPEN WiFi network does elsewhere
    # in this app - connectivity state still wins (above), nothing is more urgent than that.
    return "risk_high" if d.get("risk") == "HIGH" else d.get("type", "Unknown")
TYPE_COLOR = {"Router": "#ff6a6a", "Network": "#ff8a5a", "Camera": AMBER, "Phone": "#ff7ba3", "Printer": "#ffb36b",
              "TV/Media": "#e07bff", "Laptop": RED, "Desktop": RED, "Computer": RED, "IoT": "#c08a8a",
              "Server": "#ffd27a", "Unknown": "#8a3a3a"}
# the non-type tags row_tag() can return (connectivity/risk override type) - same colors as the matching
# tree.tag_configure() calls in _build_results(), so a device is the same color on the table and the map
TAG_COLOR = {"offline": "#6a2a2a", "noping": "#b8741a", "risk_high": "#ffb000"}


def node_color(d):
    """TOPOLOGY MAP's node color for a device - deliberately just row_tag() fed through the same two
    color tables the device TABLE already uses, so the map is never a second, independent opinion about
    what color a device 'should' be; it is always exactly whatever row_tag() already decided."""
    tag = row_tag(d)
    return TAG_COLOR.get(tag) or TYPE_COLOR.get(tag, TYPE_COLOR["Unknown"])


OEM_ENC = None


def ping_encoding():
    if ns.OS != "Windows":
        return "utf-8"
    try:
        import ctypes
        return "cp%d" % ctypes.windll.kernel32.GetOEMCP()
    except Exception:
        return "cp437"


class Tab:
    """One browser-style tab's worth of state. Every per-run concurrency primitive (queue, cancel
    event, subprocess handle, worker thread) lives here, and every worker-thread method is handed
    this exact object explicitly - never through 'self' on the App - so two tabs can genuinely run
    at the same time without one's results, STOP button or subprocess ever touching the other's.
    Main-thread-only display state (rows, console/table widgets, sort order, ...) lives here too,
    simply because each tab owns its own results area now instead of sharing one with every other
    tab; nothing about that part needs thread-safety, it just needs to not be a single shared copy."""
    _ids = itertools.count(1)

    def __init__(self):
        self.id = next(Tab._ids)
        # concurrency - touched from worker threads, always via this object, explicitly, never self.*
        self.q = queue.Queue()
        self.cancel = threading.Event()
        self.proc = None
        self.worker = None
        # run state
        self.running = False
        self.t0 = 0.0
        self.tool = "scan"
        self.extra = ""
        self.status_text = "Ready \u2014 pick a tool and press Run"
        self.finished_flag = False     # tool finished while this tab was not the one on screen
        self.alert_flag = False        # BACKGROUND WATCH found a new device while unviewed
        self.alert_new_total = 0       # cumulative new-device count this tab has ever alerted on
        self.unseen = 0                # alerts raised since this tab was last on screen (its red badge)
        self.last_secs = None          # how long the last finished run took (SCAN TIME tile)
        self.risk_filter = "ALL"       # device table: ALL / RISK (medium+high) / HIGH
        # results / table state
        self.view = "console"
        self.kind, self.devs, self.aps, self.cols, self.rid = "devs", [], [], DEV_COLS, "ip"
        self.pres, self.pmeta = [], {"hosts": 0, "ports": 0, "secs": 0.0}
        self.bts, self.band_filter = [], "ALL"
        self.apgroups = []             # physical access points from the ACCESS POINTS tool
        self.ifaces, self.prev = [], None
        self.prev_view = None          # the view (table/topo) BACK should restore - tab.prev stays a
                                        # plain (tool, kind) 2-tuple; test_ifaces_and_back.py checks that
                                        # exact shape, so the view is tracked separately rather than
                                        # changing tab.prev into a 3-tuple.
        self.sort_col, self.sort_desc = "ip", False
        self.ap_heard = 0
        self.last_text = []
        # TOPOLOGY MAP: nodes last drawn on tab.topo, for click hit-testing (plain Python list, not read
        # back from the canvas - keeps hit-testing deterministic and testable without a real display) and
        # the net_info() snapshot that produced them, so go_back() can redraw without re-scanning.
        self.topo_nodes, self.topo_info = [], {}
        # IP CAMERA: the connected camera (login kept in memory for this session only), its live view
        self.cam, self.cam_has_img, self.cam_imgref, self.cam_moving, self.cam_after = None, False, None, "", None
        self.pkt_summary = None        # last PACKET INSPECTOR traffic summary (for its stat tiles)
        self.srv_summary = None        # last SERVER SCAN summary (for its stat tiles)
        self.vuln_summary, self.vuln_count = None, 0   # last VULN SCAN summary + total findings
        self.subnet_last = None        # last SUBNET CALC result (for its stat tiles)
        self.dns_last = None           # last DNS TOOLKIT result (for its stat tiles)
        self.web_last = None           # last WEBSITE HEALTH result (for its stat tiles)
        self.report_doc = None         # last FULL REPORT HTML (for re-save)
        self.report_summary = None     # last FULL REPORT overall grade (for its stat tiles)
        self.cam_frame = self.cam_img = self.cam_status = None
        # widgets - built once by App._build_results(), filled in there
        self.results = self.table_frame = self.console_frame = self.topo_frame = None
        self.tree = self.console = self.detail = self.counter = None
        self.panel_title = None
        self.topo = self.topo_detail = None

    def log(self, text, tag="ok"):
        self.q.put(("log", text, tag))

    def label(self):
        """The tool's own name, with no markers - what the tab strip writes; the markers are drawn."""
        return next((l for k, l, _ in TOOLS if k == self.tool), self.tool.upper())

    def title(self):
        name = self.label()
        # These two are NOT mutually exclusive: a one-shot tool (PING, INFO, ...) only ever sets
        # finished_flag once it's no longer running, so for those the old either/or read fine - but
        # BACKGROUND WATCH is long-running and raises alert_flag WHILE still running (that's the whole
        # point: notice a new device without having to stop the watch first). So both marks are shown
        # together when both apply, rather than the run-dot silently hiding an unseen alert.
        mark = (" ●" if self.running else "") + (" !" if (self.finished_flag or self.alert_flag) else "")
        return f"{name}{mark}"


