    # ---- upgrades: traceroute, internet check, notifications, HTML report ------------------------------
    def _trace_route(self):
        if self.active_tab.running:
            return
        self._pending_trace = True
        self.select_tool("ping")
        self.run_tool()

    def _trace(self, tab, host):
        """TRACE ROUTE: the OS's own traceroute, streamed live, then a summary that says what it means."""
        argv, err = ns.traceroute_cmd(host)
        if not argv:
            tab.log(err, "bad")
            return
        tab.log(f"TRACE ROUTE {host}\n", "big")
        tab.log("Each line is one router on the way. '*' = that router didn't answer (common, usually harmless).\n", "dim")
        try:
            target_ip = socket.getaddrinfo(host, None)[0][4][0]
        except (OSError, IndexError):
            target_ip = ""
        try:
            tab.proc = subprocess.Popen(argv, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, **ns.NOWIN)
        except OSError as e:
            tab.log(f"Could not start traceroute: {e}", "bad")
            return
        enc, hops = ping_encoding(), []
        for raw in iter(tab.proc.stdout.readline, b""):
            line = raw.decode(enc, "ignore").rstrip()
            if not line:
                continue
            h = ns.parse_trace_line(line)
            if h:
                hops.append(h)
                tab.q.put(("extra", f"hop {h['hop']}"))
            tab.log(line, "dim" if not h else ("bad" if not h["ips"] else "ok"))
            if tab.cancel.is_set():
                return
        if tab.cancel.is_set() or not hops:
            if not hops:
                tab.log("No hops came back - the host may be unreachable.", "bad")
            return
        ips = [h["ips"][0] for h in ns.merge_hops(hops) if h["ips"]]
        with ThreadPoolExecutor(16) as ex:
            names = dict(zip(ips, ex.map(ns.hostname_of, ips)))
        tab.log("\nSUMMARY", "head")
        for line in ns.trace_lines(hops, target_ip, names):
            tab.log(line, "bad" if ("NOT reached" in line or "jumps" in line) else
                    "key" if "provider starts" in line else "ok")

    def _net_action(self, kind):
        if self.active_tab.running:
            return
        self._pending_net = kind
        self.select_tool("info")
        self.run_tool()

    def _notify_alert(self, tab, count, text=""):
        """Desktop notification for an alert - only when NetScout isn't what you're looking at, and at
        most one every 15 seconds, so a burst of findings doesn't become a burst of pop-ups."""
        if not self.notify_var.get():
            return
        try:
            focused = self.focus_displayof() is not None
        except Exception:
            focused = False
        if focused and tab is self.active_tab:
            return
        now = time.time()
        if now - self._last_notify < 15:
            return
        self._last_notify = now
        name = next((l for k, l, _ in TOOLS if k == tab.tool), "NETSCOUT")
        body = text or f"{count} new alert(s) - open NetScout to see what happened."
        threading.Thread(target=ns.notify, args=(f"NetScout - {name}", body), daemon=True).start()

    def save_report(self):
        """SAVE REPORT: the current results as one self-contained HTML page - opens in any browser,
        prints cleanly, and can be mailed to a colleague or attached to a ticket."""
        tab = self.active_tab
        if tab.running:
            return
        name = next((l for k, l, _ in TOOLS if k == tab.tool), "NETSCOUT") if tab.tool else "NETSCOUT"
        rows = cols = lines = None
        sections = []
        if tab.view in ("table", "topo") and self.cur_rows(tab):
            rows = sorted(self.cur_rows(tab), key=lambda d: self.sort_value(tab, d), reverse=tab.sort_desc)
            cols = [(c[0], c[1]) for c in tab.cols]
            if tab.kind == "devs":
                sections.append(("What was found", [ns.detection_summary(rows)["text"]], False))
                risky = [d for d in rows if d.get("risk") not in (None, "", "NONE")]
                if risky:
                    sections.append((f"Risks ({len(risky)})", [
                        f"[{d['risk']}] {d['ip']}  {d.get('label', '')}: " + "; ".join(d.get("risk_notes") or [])
                        for d in risky], True))
            elif tab.kind == "ports":
                warn = [r for r in rows if r.get("note")]
                if warn:
                    sections.append((f"Warnings ({len(warn)})", [
                        f"{r['ip']}:{r['port']} {r['service']}: {r['note']}" for r in warn], True))
        elif tab.last_text:
            lines = [str(l).rstrip("\n") for l in tab.last_text]
        else:
            messagebox.showinfo("NETSCOUT", "Nothing to put in a report yet - run a tool first.")
            return
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        path = filedialog.asksaveasfilename(defaultextension=".html",
                                            initialfile=f"netscout_{tab.tool or 'report'}_{stamp}.html",
                                            filetypes=[("HTML report", "*.html")])
        if not path:
            return
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(ns.html_report(f"{name.title()} report", rows, cols, lines, self.info, sections))
            ns.set_permissions(path, private=not self.everyone.get())
            self.set_status(f"REPORT SAVED {path} - open it in any web browser")
        except OSError as e:
            messagebox.showerror("NETSCOUT", f"Could not save the report:\n{e}")

    def w_firewall(self, tab, o):
        """FIREWALL: report whether the OS firewall is on and what this machine exposes to the network.

        This drives and reports the OS's OWN kernel firewall rather than pretending to be one - a Python
        app cannot sit in the packet path, so a home-made 'firewall' would inspect nothing and give a
        false sense of safety. What it CAN do honestly is show your real attack surface and whether the
        real firewall is guarding it.
        """
        tab.log("FIREWALL & EXPOSURE\n", "big")
        tab.log("Reading the OS firewall state and the ports this machine is listening on...\n", "dim")
        st = ns.firewall_status()
        ports = ns.listening_ports()
        lines = ns.firewall_lines(st, ports)
        for l in lines:
            tab.log(l, "bad" if (">>" in l or "THAT MATTER" in l) else ("key" if l.startswith("OS firewall") else "ok"))
        tab.last_text = lines
        if st.get("on") is False:
            tab.log("\nTo turn the firewall on, use the TURN FIREWALL ON button above (needs admin "
                    "rights). Everything it protects is listed above.", "key")

    def w_macpriv(self, tab, o):
        """MAC PRIVACY: generate a fresh, random hardware address for an adapter.

        This is the real, legitimate version of 'don't be trackable by a fixed address' - the same thing
        phones do. It changes the MAC the adapter shows on the LAN; it does NOT make you untraceable and
        does NOT change your IP (see the note it prints). Applying it needs admin and briefly drops the
        link, so it generates and shows the address, and only applies it on an explicit button press.
        """
        tab.log("MAC PRIVACY\n", "big")
        ifaces = [i for i in ns.list_interfaces() if i.get("mac") and i.get("up")]
        self._macpriv_new = ns.random_mac()
        tab.log("A freshly generated, randomised hardware address (locally-administered, as phones use):\n", "dim")
        tab.log(f"    {self._macpriv_new}\n", "big")
        if ifaces:
            tab.log("Active interfaces you could apply it to:", "head")
            for i in ifaces:
                tab.log(f"    {i['name']:<16} currently {i['mac']}", "ok")
            tab.log("\nUse the APPLY TO INTERFACE button above to set it (needs admin; the link drops "
                    "briefly). On Windows it is set in Device Manager - the tool shows you where.", "key")
        tab.log("\nHonest scope: this changes the hardware address other devices on the LAN see. It does "
                "NOT change your IP address and does NOT make you untraceable - for public-IP privacy you "
                "need a VPN or Tor, which are separate tools.", "dim")
        tab.last_text = [self._macpriv_new]

    def _known_devices(self):
        """Every device this session has scanned, as {normalised-mac: label}, so the port map can put a
        familiar name next to a MAC the switch learned. Named devices win over unnamed duplicates."""
        inv = {}
        for t in self.tabs:
            for d in getattr(t, "devs", None) or []:
                if not d.get("mac"):
                    continue
                key = ns.norm_mac(d["mac"])
                label = d.get("label") or d.get("name") or d.get("type") or ""
                if label or key not in inv:      # a named device overwrites an unnamed duplicate
                    inv[key] = label
        return inv

    def w_cable(self, tab, o):
        """SWITCH X-RAY: read a managed switch over SNMP (read-only) and show the whole picture of it -
        every port's cable health (the gigabit port quietly linking at 100 because a pair is broken), AND
        a port map of which device is plugged into each port, named from the current scan, with its VLAN."""
        tab.log("SWITCH X-RAY\n", "big")
        # its own SWITCH box (SWITCH X-RAY options); PORT SCAN's TARGET is only a fallback for older callers
        target = ((o.get("switch") or o.get("target") or "").strip()
                  or (ns.net_info() or {}).get("gateway", ""))
        if not target:
            tab.log("No switch to ask. Put the switch's IP in the SWITCH box and run again.", "bad")
            return
        tab.log(f"Reading the interface table of {target} over SNMP...\n", "dim")
        ports, err = ns.snmp_ports(target, log=lambda m: tab.log(m, "dim"), cancel=tab.cancel)
        if tab.cancel.is_set():
            return
        lines = ns.cable_lines(ports, err, host=target)
        for line in lines:
            tab.log(line, "bad" if ("REPLACE" in line or "SUSPECT" in line or err) else "ok")
        tab.last_text = lines
        # --- the port map (the X-ray): who is plugged into each port, from the switch's forwarding table ---
        if ports and not err and not tab.cancel.is_set():
            tab.log("\nMapping which device is on each port (from the switch's forwarding table)...\n", "dim")
            pm, perr = ns.switch_portmap(target, inventory=self._known_devices(), ports=ports,
                                         log=lambda m: tab.log(m, "dim"), cancel=tab.cancel)
            if not tab.cancel.is_set():
                if perr:
                    tab.log(perr, "dim")
                else:
                    maplines = ns.portmap_lines(pm, "", host=target)
                    for line in maplines:
                        tab.log(line, "key" if "uplink" in line.lower() else "ok")
                    tab.last_text = lines + ["", ""] + maplines
        bad = [p for p in ports if p["verdict"] in ("REPLACE CABLE", "SUSPECT")]
        if bad:
            tab.q.put(("alert", len(bad)))

    def w_wifisec(self, tab, o):
        """WIFI AUDIT: the security read on everything in range - open networks, obsolete encryption,
        possible evil twins, and personal hotspots inside a site that should not have any."""
        tab.log("WIFI AUDIT\n", "big")
        tab.log("Scanning several times so that networks which come and go are caught too.\n", "dim")
        aps, err = ns.wifi_scan(log=lambda m: tab.log(m, "dim"), passes=3, cancel=tab.cancel,
                                env=getattr(self, "wifi_env", ns.DEFAULT_ENV))
        if tab.cancel.is_set():
            return
        if err and not aps:
            tab.log(err, "bad")
            return
        lines = ns.wifi_audit_lines(aps)
        for line in lines:
            tab.log(line, "bad" if ("EVIL" in line or "OPEN /" in line or "OBSOLETE" in line) else "ok")
        aplist = ns.access_points(aps)
        lines += ["", f"PHYSICAL ACCESS POINTS: {len(aplist)} unit(s) behind {len(aps)} radio(s)", ""]
        for g in aplist:
            lines.append(f"  {g['vendor'] or 'unknown vendor':<28} {g['radios']} radio(s)  "
                         f"{', '.join(g['bands']) or '-':<16} {', '.join(g['ssids'])[:60]}")
        for line in lines[-(len(aplist) + 3):]:
            tab.log(line, "ok")
        rogues = ns.rogue_aps(aps)
        if rogues:
            tab.q.put(("alert", len(rogues)))
        tab.last_text = lines

    def w_audit(self, tab, o):
        """SECURITY AUDIT: one read-only health check that reuses the engine's own scan, WiFi, router
        and firewall reads, then scores the result - severity-ranked findings, each with a concrete
        fix, and an overall A-F grade. It only ever READS (it acts on nothing), and it judges only
        your own network, so a neighbour's open WiFi in range is never counted against you. It is a
        posture check, not a penetration test."""
        tab.log("SECURITY AUDIT\n", "big")
        tab.log("A read-only health check. It scores your network from what an ordinary scan can see - "
                "open ports, WiFi encryption, device risk, router integrity, this machine's firewall - "
                "and lists what to fix, worst first. It changes nothing.\n", "dim")
        # 1) devices - the same engine path DEVICE SCAN uses, with ports+vendors forced on so the audit
        #    always has the open-port and identification data it scores from (deep only if ports are on).
        # ports+vendor+deep forced on: the audit scores from open ports AND from banner/version detection
        # (deep), which is where the "known-vulnerable software" findings come from - without deep they
        # would silently never fire.
        o = dict(o, flags=dict(o.get("flags") or {}, ports=True, vendor=True, deep=True))
        devs, info = self._do_scan(tab, o)
        if tab.cancel.is_set() or devs is None:
            return
        # 2) WiFi in range - a couple of passes so networks that come and go are still caught.
        tab.log("\nChecking WiFi security...", "head")
        aps, _err = ns.wifi_scan(log=lambda m: tab.log("> " + m, "dim"), passes=2, cancel=tab.cancel,
                                 env=getattr(self, "wifi_env", ns.DEFAULT_ENV))
        if tab.cancel.is_set():
            return
        # 3) extra findings the pure scorer can't derive on its own: router/ARP integrity, and whether
        #    THIS machine's OS firewall is on. Both are read-only checks.
        extra, gwip = [], info.get("gateway", "")
        if gwip:
            try:
                ns.ping_rtt(gwip)                       # make sure the router is in the ARP table
            except Exception:
                pass
            try:
                table = ns.arp_table()
                gw_mac = ns._clean_arp(table).get(gwip, "")
                prev = ns.remember_gateway(f"audit|{gwip}", gw_mac)
                for f in ns.arp_spoof_check(table, gwip, prev):
                    extra.append({"severity": f["severity"], "title": f["kind"], "detail": f["why"],
                                  "fix": "Confirm the router was not just replaced; if not, find the host "
                                         "impersonating it (THREAT MONITOR names it) and isolate it.", "where": gwip})
            except Exception:
                pass
        try:
            fw = ns.firewall_status()
            if fw.get("on") is False:
                extra.append({"severity": "MEDIUM", "title": "This machine's firewall is off",
                              "detail": fw.get("detail", "") or "The operating-system firewall is not enabled.",
                              "fix": "Turn the OS firewall on (the FIREWALL tool can do it).", "where": info.get("ip", "")})
        except Exception:
            pass
        # 4) score it and render worst-first.
        result = ns.security_audit(devs, aps, info, extra_findings=extra)
        tab.log("", "dim")
        sev_tag = [("[!!]", "bad"), ("[!]", "bad"), ("[*]", "key"), ("[-]", "dim"), ("[i]", "dim")]
        lines = ns.audit_lines(result)
        for line in lines:
            tag = "head" if line.startswith("SECURITY POSTURE") else "ok"
            for mark, t in sev_tag:
                if mark in line:
                    tag = t
                    break
            tab.log(line, tag)
        if result["counts"].get("CRITICAL") or result["counts"].get("HIGH"):
            tab.q.put(("alert", result["counts"].get("CRITICAL", 0) + result["counts"].get("HIGH", 0),
                       f"Security audit: grade {result['grade']}"))
        tab.last_text = lines

    def w_packet(self, tab, o):
        """PACKET INSPECTOR: a passive, tcpdump/Wireshark-style look at the traffic on your network. It
        LISTENS (it never transmits a frame), then shows a packet-by-packet list and an analysis -
        protocol mix, who is talking to whom, the busiest ports, and any PLAINTEXT protocols worth
        securing. It keeps packet headers and metadata only, never the contents of a message, and needs
        administrator / sudo. Capture your own network only."""
        tab.log("PACKET INSPECTOR\n", "big")
        cap = ns.capture_capability()
        tab.log(f"Capture backend: {cap['backend']} - {cap['detail']}", "dim")
        if not cap["ok"]:
            tab.log((cap["detail"] + (" " + cap["need"] if cap["need"] else "")).strip(), "bad")
            return
        if cap["need"]:
            tab.log(cap["need"], "key")
        try:
            secs = max(1, min(int(o.get("pkt_secs") or 10), 600))
        except ValueError:
            secs = 10
        try:
            count = max(0, min(int(o.get("pkt_count") or 0), 100000))
        except ValueError:
            count = 0
        extra = f" or {count} packets" if count else ""
        tab.log(f"Listening passively for up to {secs}s{extra}... (press STOP to end early)\n", "head")
        t_start = time.time()
        recs, err = ns.capture_frames(seconds=secs, count=count or None, cancel=tab.cancel,
                                      log=lambda m: tab.log("> " + m, "dim"))
        if tab.cancel.is_set() and not recs:
            return
        if err and not recs:
            tab.log(err, "bad")
            return
        window = max(0.1, time.time() - t_start)
        summary = ns.traffic_summary(recs, window_secs=window)
        tab.pkt_summary = summary
        lines = ns.capture_lines(recs, summary)
        for line in lines:
            if line.strip().startswith("[!]") or "PLAINTEXT" in line:
                tag = "bad"
            elif line.startswith("CAPTURED") or (line and not line.startswith(" ") and line.rstrip().endswith(":")):
                tag = "head"      # section headers ("PROTOCOLS:", "TOP TALKERS...:") and the capture total
            else:
                tag = "ok"
            tab.log(line, tag)
        # tab.pkt_summary (set above) is what the stat tiles read; they are refreshed on the MAIN thread
        # by finish()/status_tick() after this worker ends - never touch Tk widgets from this thread.
        if summary["plaintext"]:
            tab.q.put(("alert", len(summary["plaintext"]), "Plaintext protocol(s) seen on the network"))
        tab.last_text = lines

    def _pkt_kpis(self, tab, timing):
        """Stat tiles for a PACKET INSPECTOR tab: packets, plaintext-protocol count, distinct talkers."""
        s = getattr(tab, "pkt_summary", None)
        if not s:
            return [("PACKETS", "—", "", False), ("PLAINTEXT", "—", "", True),
                    ("TALKERS", "—", "", False), timing]
        return [("PACKETS", str(s["packets"]), "", False),
                ("PLAINTEXT", str(len(s["plaintext"])), "", True),
                ("TALKERS", str(len(s["top_talkers"])), "", False), timing]

    def _srv_kpis(self, tab, timing):
        """Stat tiles for a SERVER SCAN tab: servers audited, worst grade, critical+high issues."""
        s = getattr(tab, "srv_summary", None)
        if not s:
            return [("SERVERS", "—", "", False), ("GRADE", "—", "", False), ("ISSUES", "—", "", True), timing]
        c = s.get("counts", {})
        issues = c.get("CRITICAL", 0) + c.get("HIGH", 0)
        wg = s.get("worst_grade", "A")
        return [("SERVERS", str(s.get("scanned", 0)), "", False),
                ("GRADE", wg, "", wg in ("C", "D", "F")),
                ("ISSUES", str(issues), "", issues > 0), timing]

    def _vuln_kpis(self, tab, timing):
        """Stat tiles for a VULN SCAN tab: total findings, criticals, hosts scanned."""
        s = getattr(tab, "vuln_summary", None)
        if not s:
            return [("VULNS", "—", "", True), ("CRITICAL", "—", "", True), ("HOSTS", "—", "", False), timing]
        c = s.get("counts", {})
        n = getattr(tab, "vuln_count", 0)
        return [("VULNS", str(n), "", n > 0),
                ("CRITICAL", str(c.get("CRITICAL", 0)), "", c.get("CRITICAL", 0) > 0),
                ("HOSTS", str(s.get("scanned", 0)), "", False), timing]

    @staticmethod
    def _abbr_count(n):
        """Compact a possibly-astronomical address count for a small tile (IPv6 ranges get huge)."""
        return f"{n:,}" if n < 10_000_000 else f"{n:.1e}"

    def _subnet_kpis(self, tab, timing):
        """Stat tiles for a SUBNET CALC tab: usable hosts, total addresses, prefix length."""
        i = getattr(tab, "subnet_last", None)
        if not i:
            return [("USABLE", "—", "", False), ("ADDRESSES", "—", "", False), ("PREFIX", "—", "", False), timing]
        return [("USABLE", self._abbr_count(i["usable"]), "", False),
                ("ADDRESSES", self._abbr_count(i["num_addresses"]), "", False),
                ("PREFIX", f"/{i['prefix']}", "", False), timing]

    def _report_kpis(self, tab, timing):
        """Stat tiles for a FULL REPORT tab: overall grade, total findings, criticals."""
        s = getattr(tab, "report_summary", None)
        if not s:
            return [("GRADE", "—", "", False), ("FINDINGS", "—", "", False), ("CRITICAL", "—", "", True), timing]
        c = s["counts"]
        total = sum(c.values())
        return [("GRADE", s["grade"], "", s["grade"] in ("C", "D", "F")),
                ("FINDINGS", str(total), "", total > 0),
                ("CRITICAL", str(c.get("CRITICAL", 0)), "", c.get("CRITICAL", 0) > 0), timing]

    def _save_full_report(self, tab, doc, suggested):
        """Main-thread save of the branded Full Report HTML: pick a file, write it, set its permissions,
        and open it in the browser. Called from the queue, so the file dialog runs on the main thread."""
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        path = filedialog.asksaveasfilename(defaultextension=".html", initialfile=f"NetScout_Report_{stamp}.html",
                                            filetypes=[("HTML report", "*.html")])
        if not path:
            self.set_status("Full report ready - not saved. (Run it again to save.)")
            return
        try:
            with open(path, "w", encoding="utf-8") as fh:
                fh.write(doc)
            ns.set_permissions(path, private=not self.everyone.get())
            self.set_status(f"FULL REPORT SAVED {path} - opening in your browser")
            try:
                webbrowser.open("file://" + os.path.abspath(path))
            except Exception:
                pass
        except OSError as e:
            messagebox.showerror("NETSCOUT", f"Could not save the report:\n{e}")

    def w_report(self, tab, o):
        """FULL REPORT: run the Security Audit, a Server Scan and a Vulnerability Scan, then build one
        branded, shareable HTML report (NetScout styling, overall A-F grade) and offer to save + open it.
        Read-only throughout - it assesses, it never attacks."""
        tab.log("FULL REPORT\n", "big")
        tab.log("Runs the security audit, a server scan and a vulnerability scan, then builds one shareable, "
                "branded HTML report with an overall A-F grade. This takes a little while. Read-only.\n", "dim")
        o = dict(o, flags=dict(o.get("flags") or {}, ports=True, vendor=True, deep=True))
        tab.log("1/4  Scanning the network...", "head")
        devs, info = self._do_scan(tab, o)
        if tab.cancel.is_set() or devs is None:
            return
        tab.log("2/4  Auditing network posture (WiFi, router, firewall)...", "head")
        aps, _e = ns.wifi_scan(log=lambda m: None, passes=1, cancel=tab.cancel,
                               env=getattr(self, "wifi_env", ns.DEFAULT_ENV))
        extra, gw = [], info.get("gateway", "")
        try:
            if gw:
                ns.ping_rtt(gw)
                table = ns.arp_table()
                prev = ns.remember_gateway(f"report|{gw}", ns._clean_arp(table).get(gw, ""))
                for fd in ns.arp_spoof_check(table, gw, prev):
                    extra.append({"severity": fd["severity"], "title": fd["kind"], "detail": fd["why"],
                                  "fix": "Confirm the router was not replaced; otherwise isolate the impersonating host.",
                                  "where": gw})
            fw = ns.firewall_status()
            if fw.get("on") is False:
                extra.append({"severity": "MEDIUM", "title": "This machine's firewall is off",
                              "detail": fw.get("detail", "") or "The OS firewall is not enabled.",
                              "fix": "Turn the OS firewall on.", "where": info.get("ip", "")})
        except Exception:
            pass
        audit = ns.security_audit(devs, aps, info, extra_findings=extra)
        if tab.cancel.is_set():
            return
        server_list = ns.detect_servers(devs)
        tab.log(f"3/4  Auditing {len(server_list)} server(s)...", "head")
        servers = ns.server_scan(server_list, cancel=tab.cancel, log=lambda m: None) if server_list else None
        if tab.cancel.is_set():
            return
        tab.log("4/4  Scanning every host for vulnerabilities...", "head")
        vulns = ns.vuln_scan(devs, cancel=tab.cancel, log=lambda m: None)
        if tab.cancel.is_set():
            return
        data = {"title": "Network Security Report", "info": info, "devices": devs, "audit": audit,
                "servers": servers, "vulns": vulns, "generated": time.strftime("%Y-%m-%d %H:%M")}
        doc = ns.report_html(data)
        overall = ns.grade_findings(ns._collect_findings(data))
        tab.report_doc, tab.report_summary = doc, overall
        tab.log("", "dim")
        tab.log(f"REPORT READY - overall grade {overall['grade']}  ({overall['score']}/100)", "big")
        tab.log(overall["summary"], "ok")
        tab.log(f"\n{len(devs)} device(s)  ·  audit grade {audit['grade']}  ·  "
                f"{(servers['summary']['scanned'] if servers else 0)} server(s) audited  ·  "
                f"{len(vulns['vulns'])} vulnerability finding(s)", "ok")
        tab.log("\nChoose where to save the HTML report - it opens in your browser; print it to PDF to share.", "key")
        tab.last_text = [f"NetScout Full Report - grade {overall['grade']} ({overall['score']}/100)",
                         overall["summary"]]
        tab.q.put(("fullreport", doc, "NetScout report"))
        if overall["counts"].get("CRITICAL") or overall["counts"].get("HIGH"):
            tab.q.put(("alert", overall["counts"].get("CRITICAL", 0) + overall["counts"].get("HIGH", 0),
                       f"Full report: overall grade {overall['grade']}"))

    def _web_kpis(self, tab, timing):
        """Stat tiles for a WEBSITE HEALTH tab: HTTP status, grade, response time."""
        r = getattr(tab, "web_last", None)
        if not r:
            return [("STATUS", "—", "", False), ("GRADE", "—", "", False), ("RESP", "—", "", False), timing]
        status = "DOWN" if r["error"] else str(r["status"])
        bad = bool(r["error"]) or (r.get("status") or 0) >= 400
        return [("STATUS", status, "", bad), ("GRADE", r["grade"], "", r["grade"] in ("C", "D", "F")),
                ("RESP", f"{r['ms']:.0f}", "ms", False), timing]

    def w_web(self, tab, o):
        """WEBSITE HEALTH: fetch a site (following redirects), report status + response time, inspect the TLS
        certificate and the common security response-headers, and grade it A-F. An ordinary web request -
        it does not attack the site."""
        tab.log("WEBSITE HEALTH\n", "big")
        url = (o.get("web_url") or "").strip()
        if not url:
            tab.log("Enter a website to check, e.g. example.com or https://example.com/health.", "key")
            return
        try:
            ns.parse_target_url(url)
        except ValueError as e:
            tab.log(str(e), "bad")
            return
        tab.log(f"Checking {url} ...\n", "head")
        res = ns.web_check(url)
        tab.web_last = res
        self._log_report(tab, ns.web_lines(res))
        c = res["counts"]
        if c.get("CRITICAL") or c.get("HIGH"):
            tab.q.put(("alert", c.get("CRITICAL", 0) + c.get("HIGH", 0), f"Website health: grade {res['grade']}"))
        tab.last_text = ns.web_lines(res)

    def _dns_kpis(self, tab, timing):
        """Stat tiles for a DNS TOOLKIT tab: answer count, resolver used, fastest response time."""
        r = getattr(tab, "dns_last", None)
        if not r:
            return [("ANSWERS", "—", "", False), ("RESOLVER", "—", "", False), ("RESP", "—", "", False), timing]
        total = sum(len(recs) for _t, recs, _m in r["blocks"])
        ms = [m["ms"] for _t, _r, m in r["blocks"] if m.get("ms") is not None]
        return [("ANSWERS", str(total), "", total == 0),
                ("RESOLVER", (r["server"] or "—")[:15], "", False),
                ("RESP", (f"{min(ms):.0f}" if ms else "—"), "ms" if ms else "", False), timing]

    def w_dns(self, tab, o):
        """DNS TOOLKIT: forward / reverse DNS and the common record types, via the system resolver or one
        you name. An IP (or TYPE=ALL) does a reverse / multi-record lookup; otherwise a single-type query."""
        tab.log("DNS TOOLKIT\n", "big")
        name = (o.get("dns_name") or "").strip()
        if not name:
            tab.log("Enter a hostname to look up (e.g. example.com), or an IP address for a reverse lookup.", "key")
            return
        rtype = (o.get("dns_type") or "A").strip().upper()
        server = (o.get("dns_server") or "").strip() or None
        try:
            ns.ipaddress.ip_address(name)
            is_ip = True
        except ValueError:
            is_ip = False
        if is_ip or rtype in ("", "ALL", "ANY"):
            res = ns.dns_lookup(name, server=server)
        else:
            recs, meta = ns.dns_query(name, rtype, server=server)
            res = {"reverse": rtype == "PTR", "server": meta["server"], "blocks": [(rtype, recs, meta)]}
        tab.dns_last = res
        lines = ns.dns_lines(res)
        for line in lines:
            first = line.split()[0] if line and not line.startswith(" ") else ""
            tab.log(line, "head" if (line.startswith("DNS") or first in ns.DNS_TYPES) else
                    "bad" if "reachable" in line else "ok")
        tab.last_text = lines

    def w_subnet(self, tab, o):
        """SUBNET CALCULATOR: pure IPv4/IPv6 subnet maths - no network traffic. Prints the network,
        broadcast, usable host range, counts, netmask and wildcard for the entered network, and can split
        it into equal /N subnets."""
        tab.log("SUBNET CALCULATOR\n", "big")
        text = (o.get("subnet_in") or "").strip()
        try:
            info = ns.subnet_info(text)
        except ValueError as e:
            tab.log(str(e), "bad")
            return
        tab.subnet_last = info
        lines = ns.subnet_lines(info)
        for line in lines:
            tab.log(line, "head" if line.startswith("SUBNET") else "ok")
        div = (o.get("subnet_div") or "").strip()
        if div:
            try:
                subs, note = ns.subnet_split(text, div)
                tab.log(f"\nSPLIT  {note}:", "head")
                for s in subs[:256]:
                    tab.log(f"  {s}", "dim")
                if len(subs) > 256:
                    tab.log(f"  ... and {len(subs) - 256:,} more in the saved list", "dim")
                lines = lines + ["", f"SPLIT {note}:"] + ["  " + s for s in subs]
            except ValueError as e:
                tab.log(str(e), "bad")
        tab.last_text = lines

    def _log_report(self, tab, lines):
        """Print audit/scan report lines with consistent severity colouring (shared by AUDIT, SERVER SCAN
        and VULN SCAN) - criticals/highs red, mediums highlighted, section headers and grades emphasised."""
        for line in lines:
            s = line.strip()
            if s.startswith(("[!!]", "[!]")) or "PLAINTEXT" in line:
                tag = "bad"
            elif s.startswith("[*]"):
                tag = "key"
            elif s.startswith(("[-]", "[i]", "FIX:")):
                tag = "dim"
            elif line and set(line) == {"="}:
                tag = "dim"
            elif line and not line.startswith(" ") and ("GRADE" in line or line.isupper()
                    or line.rstrip().endswith(":")
                    or line.startswith(("SERVER SCAN", "VULNERABILITY SCAN", "SECURITY POSTURE"))):
                tag = "head"
            elif s.endswith(":") and s.isupper():
                tag = "key"
            else:
                tag = "ok"
            tab.log(line, tag)

    def w_server(self, tab, o):
        """SERVER SCAN: find the servers on the LAN (anything with a service listening) and run a full
        security audit on each - open ports, software versions, known-vulnerable services and TLS
        certificates - grading every server A-F. Reads only; it never exploits anything. The optional
        SERVERS field restricts the audit to specific IPs; blank audits every server found."""
        tab.log("SERVER SCAN\n", "big")
        tab.log("Finds the servers on your network and runs a full security audit on each - open ports, "
                "software versions, known vulnerabilities and TLS certificates - then grades each A-F with a "
                "fix for every issue. It only reads; it does not exploit anything.\n", "dim")
        o = dict(o, flags=dict(o.get("flags") or {}, ports=True, vendor=True))
        devs, info = self._do_scan(tab, o)
        if tab.cancel.is_set() or devs is None:
            return
        servers = ns.detect_servers(devs)
        restrict = [x for x in (o.get("srv_targets") or "").replace(",", " ").split() if x]
        if restrict:
            servers = [s for s in servers if s["ip"] in restrict]
        if not servers:
            tab.log("\nNo servers detected" + (" matching your filter (" + ", ".join(restrict) + ")."
                    if restrict else " - nothing on the network was listening on a server port."), "key")
            return
        tab.log(f"\nDetected {len(servers)} server(s):", "head")
        for s in servers:
            tab.log(f"  - {s['ip']:<16}[{s['role']}]  ({s['why']})", "ok")
        tab.log("\nRunning the full audit - this scans many ports per host, so give it a moment...\n", "head")
        res = ns.server_scan(servers, cancel=tab.cancel, log=lambda m: tab.log("> " + m, "dim"))
        if tab.cancel.is_set() and not res["servers"]:
            return
        tab.srv_summary = res["summary"]
        lines = ns.server_scan_lines(res)
        tab.log("", "dim")
        self._log_report(tab, lines)
        c = res["summary"]["counts"]
        if c.get("CRITICAL") or c.get("HIGH"):
            tab.q.put(("alert", c.get("CRITICAL", 0) + c.get("HIGH", 0),
                       f"Server scan: worst grade {res['summary']['worst_grade']}"))
        tab.last_text = lines

    def w_vuln(self, tab, o):
        """VULN SCAN: deep-scan every device on the network and list everything that is known-vulnerable or
        dangerously exposed, worst-first, each with a fix. Detection is version/exposure based (service
        banners, open ports, certificates) - 'update, or confirm it's patched' - not an exploit scanner."""
        tab.log("VULNERABILITY SCAN\n", "big")
        tab.log("Deep-scans every device on the network and lists everything known-vulnerable or dangerously "
                "exposed - outdated/end-of-life software, unauthenticated databases, expired or self-signed "
                "certificates, risky open services - worst-first, with a fix for each.\n", "dim")
        o = dict(o, flags=dict(o.get("flags") or {}, ports=True, vendor=True))
        devs, info = self._do_scan(tab, o)
        if tab.cancel.is_set() or devs is None:
            return
        tab.log(f"\nDeep-scanning {len(devs)} host(s) for known vulnerabilities and exposures...\n", "head")
        res = ns.vuln_scan(devs, cancel=tab.cancel, log=lambda m: tab.log("> " + m, "dim"))
        if tab.cancel.is_set() and not res["servers"]:
            return
        tab.vuln_summary = res["summary"]
        tab.vuln_count = len(res["vulns"])
        lines = ns.vuln_scan_lines(res)
        tab.log("", "dim")
        self._log_report(tab, lines)
        c = res["summary"]["counts"]
        if c.get("CRITICAL") or c.get("HIGH"):
            tab.q.put(("alert", c.get("CRITICAL", 0) + c.get("HIGH", 0),
                       f"Vuln scan: {len(res['vulns'])} finding(s)"))
        tab.last_text = lines

    def w_dhcp(self, tab, o):
        """DHCP CHECK: ask the network for an address and count who answers. Two answers means someone
        has plugged in a second DHCP server, which hands out addresses for a network it knows nothing
        about - a classic cause of 'some machines work, some don't'."""
        tab.log("DHCP CHECK\n", "big")
        tab.log("Broadcasting one DHCP DISCOVER and listening for offers. No address is accepted and no "
                "request is ever sent, so nothing on the network is changed by this.\n", "dim")
        info = ns.net_info() or {}
        servers, note = ns.dhcp_servers(seconds=6.0, log=lambda m: tab.log(m, "dim"), cancel=tab.cancel)
        if tab.cancel.is_set():
            return
        lines = ns.dhcp_lines(servers, note, expected=info.get("dhcp", ""))
        for line in lines:
            tab.log(line, "bad" if ("MORE THAN ONE" in line or "NOT the expected" in line) else "ok")
        if len(servers) > 1:
            tab.q.put(("alert", len(servers) - 1))
        tab.last_text = lines

    SEV_TAG = {"alert": "alert", "warn": "key", "info": "dim"}

    @staticmethod
    def _sparkline(values, width=24):
        """A tiny inline bar chart from a run of numbers, for the trend line in the Guardian log."""
        vals = [float(v) for v in list(values)[-width:]]
        if not vals:
            return ""
        bars = "▁▂▃▄▅▆▇█"
        lo, hi = min(vals), max(vals)
        span = (hi - lo) or 1.0
        return "".join(bars[min(len(bars) - 1, int((v - lo) / span * (len(bars) - 1)))] for v in vals)

    def _guardian_pass(self, prev, devs, cfg, approved=None):
        """One Guardian pass, as pure logic (no I/O, so it's unit-testable): the change feed vs the
        previous snapshot, plus baseline drift when enabled, with alerts about already-approved devices
        filtered out so a network where phones come and go doesn't cry wolf."""
        approved = ns.approved_macs() if approved is None else approved
        events = ns.guardian_changes(prev, devs) if prev else []
        if cfg.get("baseline_on"):
            events = events + ns.guardian_baseline_drift(devs)
        return [e for e in events
                if not (e.get("kind") in ("device_new", "baseline_new")
                        and ns.norm_mac(e.get("mac", "")) in approved)]

    def guardian_set_baseline(self):
        """Approve the devices currently in the table as the Guardian's known-good baseline."""
        tab = getattr(self, "active_tab", None)
        devs = getattr(tab, "devs", None) if tab else None
        if not devs:
            messagebox.showinfo("NETSCOUT - Guardian",
                                "Run DEVICE SCAN (or one BACKGROUND WATCH pass) first, then approve the "
                                "result here. Guardian will then flag anything that drifts from it.")
            return
        n = ns.guardian_baseline_save(devs)
        self.guard_baseline_var.set(True)
        cfg = ns.guardian_config_load()
        cfg["baseline_on"] = True
        ns.guardian_config_save(cfg)
        self.set_status(f"Guardian baseline approved: {n} device(s). Drift from this is now flagged.")

    def guardian_clear_baseline(self):
        ns.guardian_baseline_clear()
        self.set_status("Guardian baseline cleared - drift checks are off until you approve a new one.")

    def w_monitor(self, tab, o):
        """BACKGROUND WATCH - the 24/7 Guardian. Re-scans on an interval (STOP to end); each pass is saved
        to the scan history and diffed against the pass before it into a plain-language change feed
        (new / departed devices, newly opened ports, rising risk, vendor swaps), checked against the
        approved baseline when that's on, and - for anything at or above the chosen severity - a bell
        rings, the tab is marked, and the change is pushed to e-mail and/or a chat webhook, so you're told
        even with NetScout closed. Always scans every device type (the SHOW filter is a DEVICE SCAN display
        choice; hiding a type here would defeat the one feature whose whole job is noticing things)."""
        try:
            interval = max(0.1, min(float(o["watch_interval"] or 5), 1440.0)) * 60.0
        except ValueError:
            interval = 300.0
        # take the current settings off the controls, merge onto the saved file (so SMTP details the file
        # holds are kept), and save - the running watch and the config file then always agree.
        url = self.guard_webhook_var.get().strip()
        cfg = ns.guardian_config_load()
        cfg.update({"interval": interval / 60.0, "desktop": bool(self.notify_var.get()),
                    "min_severity": self.guard_sev_var.get() or "warn",
                    "baseline_on": bool(self.guard_baseline_var.get()),
                    "email_on": bool(self.guard_email_var.get()),
                    "webhook_url": url, "webhook_on": bool(url)})
        ns.guardian_config_save(cfg)

        channels = (["desktop"] if cfg["desktop"] else []) + (["e-mail"] if cfg["email_on"] else []) \
            + (["webhook"] if cfg["webhook_on"] else [])
        tab.log("24/7 GUARDIAN   (background watch)\n", "big")
        tab.log(f"re-scanning every {interval / 60:g} min - watching for new or departed devices, newly "
                "opened ports, and rising risk. Press STOP to end.", "dim")
        tab.log(f"alerting at '{cfg['min_severity']}' and above via: {', '.join(channels) or 'nothing (every channel off)'}"
                + ("   -   baseline drift ON" if cfg["baseline_on"] else ""), "dim")
        if cfg["baseline_on"] and not ns.guardian_baseline_load().get("devices"):
            tab.log("baseline drift is on, but no baseline is approved yet - after a scan, use the EXPORT "
                    "menu > 'Approve current devices as Guardian baseline'.", "dim")

        snaps = ns.list_snapshots()
        prev = ns.load_snapshot(snaps[0]["stamp"]) if snaps else []
        if prev:
            tab.log(f"first-pass baseline: the last saved scan ({ns.stamp_pretty(snaps[0]['stamp'])}) - "
                    "anything different from it is flagged on pass 1 too.", "dim")
        else:
            tab.log("no earlier scan on record - pass 1 just establishes the picture; changes are flagged "
                    "from pass 2 on.", "dim")

        passn = 0
        while not tab.cancel.is_set():
            passn += 1
            devs, _info = self._do_scan(tab, dict(o, type="ALL"))     # also saves this pass to the history
            if tab.cancel.is_set() or devs is None:
                return
            events = self._guardian_pass(prev, devs, cfg)
            prev = [ns._slim_device(d) for d in devs]                 # next pass compares against this one
            floor = ns._SEVERITY_RANK.get(cfg["min_severity"], 1)
            hot = [e for e in events if ns._SEVERITY_RANK.get(e.get("severity"), 0) >= floor]
            if events:
                for e in events[:40]:
                    tab.log(f"  {e.get('severity', 'info').upper():<5} {e.get('text', '')}",
                            self.SEV_TAG.get(e.get("severity"), "dim"))
                if len(events) > 40:
                    tab.log(f"  ...and {len(events) - 40} more change(s)", "dim")
            else:
                tab.log(f"pass {passn}: {len(devs)} device(s), nothing changed.", "dim")
            if hot:
                # desktop bell + tab marker through the existing alert path; e-mail/webhook via the engine
                tab.q.put(("alert", len(hot), "; ".join(e.get("text", "") for e in hot[:3])))
                for ch, ok, msg in ns.guardian_dispatch(events, dict(cfg, desktop=False)):
                    tab.log(f"  -> {ch}: {msg}", "dim" if ok else "bad")
            trend = ns.guardian_trends(limit=24)
            if len(trend) >= 2:
                tab.log(f"  trend  devices {self._sparkline(p['devices'] for p in trend)} {trend[-1]['devices']}"
                        f"    risks {self._sparkline(p['risks'] for p in trend)} {trend[-1]['risks']}", "dim")
            tab.q.put(("extra", f"pass {passn} - next in {interval / 60:g} min"))
            tab.cancel.wait(interval)

    # ---- table ----------------------------------------------------------
    # The mockup's device table reads STATUS / IP ADDRESS / DEVICE / NAME / RISK - those lead, and every
    # other column follows in its usual order, a slide of the horizontal scrollbar away. Only the DISPLAY
    # order changes: each row's values keep their positions in DEV_COLS (saved files and tests rely on it).
    DEV_FIRST = ("status", "ip", "label", "name", "risk_disp", "type")
    BT_FIRST = ("signal", "dist", "name", "status", "kind")

    def display_order(self, cols):
        keys = [c[0] for c in cols]
        lead = self.DEV_FIRST if cols is DEV_COLS else self.BT_FIRST if cols is BT_COLS else ()
        first = [k for k in lead if k in keys]
        return first + [k for k in keys if k not in first]

    PANEL_TITLES = {"devs": "Devices on the network", "aps": "WiFi networks in range", "ports": "Open ports",
                    "bt": "Bluetooth devices nearby", "ifaces": "Network interfaces on this machine",
                    "apgroups": "Access points in range"}

    def set_columns(self, tab, cols, rid):
        tab.cols, tab.rid = cols, rid
        kind = {id(DEV_COLS): "devs", id(AP_COLS): "aps", id(PORT_COLS): "ports", id(BT_COLS): "bt",
                id(IFACE_COLS): "ifaces", id(APS_COLS): "apgroups"}.get(id(cols), tab.kind)
        if tab.panel_title is not None:
            try:
                tab.panel_title.configure(text=self.PANEL_TITLES.get(kind, "Results"))
            except Exception:
                pass
        tab.tree.configure(columns=[c[0] for c in cols], displaycolumns=self.display_order(cols))
        for key, title, w in cols:
            # left-aligned like the mockup, over the cell text (which starts two spaces in)
            tab.tree.heading(key, text="  " + title, anchor="w", command=lambda k=key, t=tab: self.sort_by(t, k))
            # stretch=False is the fix for a real bug: with ttk's default stretch=True, ttk is free to
            # shrink/grow columns to make everything fit the visible width, which can quietly make the
            # table's total content width hug the frame width instead of genuinely exceeding it - leaving
            # the horizontal scrollbar with little or no real range to drag, even though columns are wide.
            # Fixed widths that stay fixed are what actually gives the scrollbar something to do.
            tab.tree.column(key, width=w, minwidth=45, anchor="w", stretch=False)

    def base_rows(self, tab):
        """The table's rows before the live search box is applied (band filter for APs still applies)."""
        if tab.kind == "aps" and tab.band_filter != "ALL":
            want = tab.band_filter.replace(" GHZ", " GHz").replace("GHZ", "GHz")
            return [a for a in tab.aps if a.get("band") == want]
        return {"devs": tab.devs, "aps": tab.aps, "ports": tab.pres, "bt": tab.bts,
                "ifaces": tab.ifaces, "apgroups": tab.apgroups}[tab.kind]

    @staticmethod
    def _row_matches(row, terms):
        """True if every search term appears somewhere in the row's text/number fields (AND search)."""
        hay = " ".join(str(v) for v in row.values() if isinstance(v, (str, int, float))).lower()
        return all(t in hay for t in terms)

    def cur_rows(self, tab):
        rows = self.base_rows(tab)
        q = (getattr(tab, "search", "") or "").strip().lower()
        if q:
            terms = q.split()
            rows = [r for r in rows if self._row_matches(r, terms)]
        return rows

    def _apply_search(self, tab):
        """Re-render the current table through the live search box and update the little match counter."""
        tab.search = (tab.search_var.get() if getattr(tab, "search_var", None) else "").strip()
        if getattr(tab, "tree", None) is None or tab.kind not in ("devs", "aps", "ports", "bt", "ifaces", "apgroups"):
            return
        self.render_table(tab)
        self.update_counter(tab)
        if getattr(tab, "search_count", None) is not None:
            if tab.search:
                shown, total = len(self.cur_rows(tab)), len(self.base_rows(tab))
                tab.search_count.configure(text=f"{shown}/{total}", fg=(SOFT if shown else AMBER))
            else:
                tab.search_count.configure(text="")

    def focus_search(self, *_):
        """Ctrl+F: jump to the active tab's search box."""
        tab = getattr(self, "active_tab", None)
        w = getattr(tab, "search_entry", None) if tab else None
        if w is not None:
            try:
                w.focus_set()
            except Exception:
                pass
        return "break"

    def dot_of(self, tab, d):
        """Colour of a row's status dot (mockup: green online, pink new, amber needs a look, grey gone)."""
        k = tab.kind
        if k == "devs":
            st = d.get("state") or d.get("status")
            if st == "OFFLINE":
                return "grey"
            if d.get("is_new") or st == "NEW":
                return "pink"
            if st == "NO PING":
                return "amber"
            return "red" if d.get("risk") == "HIGH" else "green"
        if k == "aps":
            if d.get("connected"):
                return "white"
            if d.get("hot") not in (None, "", "-"):
                return "pink"
            return {"OPEN": "red", "WEAK": "amber"}.get(d.get("risk"), "green")
        if k == "ports":
            return "amber" if d.get("note") else "green"
        if k == "bt":
            if d.get("tracker"):
                return "red" if d.get("separated") else "amber"
            return "blue" if (d.get("name") not in (None, "", "<unnamed>") or d.get("vendor")) else "grey"
        if k == "ifaces":
            return "green" if d.get("up") else "grey"
        if k == "apgroups":
            return "green" if d.get("ip") else "blue"
        return "green"

    def tag_of(self, tab, d):
        if tab.kind == "ports":
            return "pt_warn" if d.get("note") else "ap_ok"
        if tab.kind == "bt":
            return "ap_ok" if (d.get("name") not in (None, "", "<unnamed>") or d.get("vendor")) else "bt_unknown"
        if tab.kind == "ifaces":
            return "ap_ok" if d.get("up") else "offline"
        if tab.kind == "devs":
            return row_tag(d)
        if d.get("connected"):
            return "ap_me"
        is_hot = d.get("hot") not in (None, "", "-")
        return ({"OPEN": "ap_open", "WEAK": "ap_weak", "BEST": "ap_best"}.get(d.get("risk"))
                or ("ap_hot" if is_hot else "ap_ok"))

    def sort_value(self, tab, d):
        key = tab.sort_col
        if key == "threat_disp":                      # PRIORITY sorts by the numeric attention score
            return (0, d.get("threat", 0), "")
        v = d.get({"signal": "sig", "ch": "channel", "dist": "dist_m"}.get(key, key))
        if v in (None, "", "-"):
            return (1, 0, "")
        if key in ("ip", "ipv4"):
            try:
                return (0, int(ipaddress.ip_address(v)), "")
            except ValueError:
                pass
        if isinstance(v, (int, float)):
            return (0, v, "")
        return (0, 0, str(v).lower())

    def render_table(self, tab):
        tab.tree.delete(*tab.tree.get_children())
        for d in sorted(self.cur_rows(tab), key=lambda d: self.sort_value(tab, d), reverse=tab.sort_desc):
            # two leading spaces per cell - without them, left-aligned text in one column can sit right up
            # against the previous column's boundary with no visible gap. Padding here only changes what is
            # DISPLAYED; sorting/filtering/tagging all read the untouched dict d, table_text() (SAVE TXT)
            # builds its own text from d directly too, and copy_row() strips it back off before copying.
            dot = self.dot_imgs.get(self.dot_of(tab, d))
            extra = {"image": dot} if dot is not None else {}
            tab.tree.insert("", "end", iid=d[tab.rid], tags=(self.tag_of(tab, d),),
                             values=[f"  {d.get(c[0]) or '-'}" for c in tab.cols], **extra)

    def sort_by(self, tab, col):
        tab.sort_desc = (not tab.sort_desc) if col == tab.sort_col else False
        tab.sort_col = col
        if self.cur_rows(tab):
            self.render_table(tab)

    def on_select(self, tab, _e):
        sel = tab.tree.selection()
        d = next((x for x in self.cur_rows(tab) if sel and x[tab.rid] == sel[0]), None)
        if not d:
            return
        if tab.kind == "apgroups":
            parts = [f"BSSID {d.get('bssid', '')}", f"vendor: {d.get('vendor') or 'unknown'}",
                     f"{d.get('radiosd', '1')} radio(s)", f"SSID(s): {d.get('ssid', '')}",
                     f"bands: {d.get('bandsd', '-')}  ch {d.get('ch', '-')}", f"security: {d.get('securityd', '-')}"]
            parts.append(f"IP on your network: {d['ip']}" if d.get("ip") else
                         "not on your network (a neighbour's AP heard over the air - it has no IP you can see)")
            parts.append(f"distance ~{d.get('dist', '-')} (estimate from signal - a radius, not an exact spot; "
                         "use LOCATE to walk to it)")
            if d.get("hot") not in (None, "", "-"):
                parts.append(f"{d['hot']}")
            tab.detail.configure(text="  |  ".join(parts))
            return
        if tab.kind == "aps":
            hint = {"OPEN": "OPEN network - traffic is not encrypted.",
                    "WEAK": "Outdated security (WEP / WPA1).",
                    "BEST": "WPA3 only - the strongest security currently available, no WPA2 downgrade path."
                    }.get(d["risk"], "")
            band_note = f"{d.get('band') or '-'} ch {d['ch']}" + (
                f", {d['width']} wide" if d.get("width") and d["width"] != "-" else "")
            parts = [d["ssid"], f"BSSID {d['bssid']}", f"vendor: {d.get('vendor') or '-'}",
                     band_note, d.get("std_full") or d["std"], f"security: {d['security']} ({d['risk']})",
                     "you are connected - IP details filled in" if d.get("connected") else
                     "not joined - IP / gateway / DHCP are only visible on a network you are connected to"]
            if d.get("grade") and d["grade"] != "?":
                parts.append(f"security grade {d['grade']}: " + (d.get("grade_why") or [""])[0])
            # PMF and WPS only show when the OS scanner actually reported them (richest on Linux's iw)
            if d.get("pmf") is True:
                parts.append("management frames protected (PMF/802.11w)")
            if d.get("wps") is True:
                parts.append("WPS enabled - a known weak point, best turned off")
            if hint:
                parts.append(hint)
            if d.get("hot") not in (None, "", "-"):
                parts.append(f"{d['hot']}: {d['hot_why']} (a guess from the name / MAC)")
            stable_txt = {"yes": "steady signal", "no": "signal varied a lot between passes"}.get(d.get("stable"), "")
            parts.append(f"distance {d.get('dist', '-')} (rough, from signal strength, {d.get('dbm', '-')} dBm est.)"
                         f"  |  heard in {d['seen']} pass(es)" + (f"  |  {stable_txt}" if stable_txt else ""))
            tab.detail.configure(text="  |  ".join(parts))
            return
        if tab.kind == "ports":
            tab.detail.configure(text="  |  ".join([
                f"{d['ip']}:{d['port']}/{d['proto'].lower()}", f"service: {d['service']}",
                f"banner: {d['banner'] or '-'}", d["note"] or "no known issue for this port",
                f"name: {d.get('name') or '-'}", f"MAC: {d.get('mac') or '-'}"]))
            return
        if tab.kind == "bt":
            tab.detail.configure(text="  |  ".join([
                d.get("name") or "<unnamed>", f"kind: {d.get('kind') or '-'}",
                f"transport: {d.get('transport', 'BLE')}", f"address: {d['address']}",
                f"vendor: {d.get('vendor') or ('randomised address' if d.get('mac_random') else '-')}",
                f"distance {d.get('dist', '-')}, likely {d.get('dist_range', '-')} (from signal strength)",
                f"heard {d.get('seen', 1)}x"]
                + ([f"TRACKER: {d['tracker']} - {d.get('tracker_note') or ''}"] if d.get("tracker") else [])
                + ([d["beacon"]] if d.get("beacon") else [])
                + ([f"announces: {', '.join(d['apple_msgs'])}"] if d.get("apple_msgs") else [])))
            return
        if tab.kind == "ifaces":
            tab.detail.configure(text="  |  ".join([
                d["name"], "UP" if d.get("up") else "DOWN", f"MAC: {d.get('mac') or '-'}",
                f"IPv4: {d.get('ipv4') or '-'}", f"IPv6: {d.get('ipv6') or '-'}"]))
            return
        tab.detail.configure(text=self.device_detail_text(d))

    def device_detail_text(self, d):
        """The devices table's own detail-line text for one device - factored out of on_select() so
        TOPOLOGY MAP's node click can show the identical detail text without duplicating it."""
        up, web = d.get("upnp") or {}, d.get("http") or {}
        parts = [f"{d['label']}", f"brand: {d.get('brand') or '-'}", f"model: {d.get('model') or '-'}",
                 f"vendor: {d.get('vendor') or '-'}", f"open ports: {', '.join(map(str, d.get('ports', []))) or '-'}",
                 f"announces: {', '.join(ns.service_list({'services': d.get('mdns_svc') or []})) or '-'}",
                 f"web: {' | '.join(x for x in web.values() if x) or '-'}",
                 f"upnp: {up.get('name') or '-'}", f"ttl: {d.get('ttl') or '-'}",
                 f"risk: {d.get('risk_disp') or d.get('risk') or 'NONE'}"]
        if d.get("wsd_types"):     # only when it answered WS-Discovery - most devices don't, no '-' clutter
            parts.insert(6, "ws-discovery: " + " ".join(d["wsd_types"])
                         + (f" ({d['wsd_model']})" if d.get("wsd_model") else ""))
        if d.get("risk_notes"):
            parts.append("; ".join(d["risk_notes"]))
        parts.append(f"note/tag: {d.get('note') or '-'}  (right-click a row to edit)")
        return "  |  ".join(parts)

    def on_double(self, tab, _e):
        sel = tab.tree.selection()
        d = (next((x for x in self.cur_rows(tab) if sel and x[tab.rid] == sel[0]), None)
             if tab.kind in ("devs", "ports") else None)
        if d and not tab.running:
            self.ping_host.set(d["ip"])
            self.select_tool("ping")
            self.run_tool()

    def copy_row(self, tab, _e):
        sel = tab.tree.selection()
        if sel:
            self.clipboard_clear()
            # .strip() removes the two-space display padding from render_table() - copied/pasted text
            # should not carry that, only the table on screen should.
            self.clipboard_append("\t".join(str(v).strip() for v in tab.tree.item(sel[0], "values")))

    def fill_table(self, tab, devs, info):
        # the table's "ipv4" column is a deliberate duplicate of the existing "ip" field, shown again next
        # to "ipv6" so both address families sit side by side at the end of the table instead of ipv4 only
        # being visible all the way over at the far-left "IP ADDRESS" column - no new data to collect, it's
        # the same value the device was already found under.
        for d in devs:
            d["ipv4"] = d.get("ip", "")
        ns.rank_devices(devs)                       # engine: score each device's "fix this first" priority
        for d in devs:
            d["threat_disp"] = f"{d.get('threat_level', 'OK')} {d['threat']}" if d.get("threat") else "OK"
        tab.devs, tab.kind = devs, "devs"
        self.set_columns(tab, DEV_COLS, "ip")
        tab.sort_col, tab.sort_desc = "ip", False
        self.show_view(tab, "table")
        self.render_table(tab)
        self.update_counter(tab)
        top = max(devs, key=lambda d: d.get("threat", 0), default=None)
        pri = (f"   -   ▶ Top priority: {top.get('label') or top.get('ip')} "
               f"({top.get('threat_level')} {top.get('threat')}) - {top.get('threat_why')}."
               if top and top.get("threat") else "")
        tab.detail.configure(text=ns.detection_summary(devs)["text"] + pri +
                             "   -   Select a device to see brand, model, vendor, open ports and web banner.")

    def fill_ports(self, tab, rows, meta):
        tab.pres, tab.pmeta, tab.kind = rows, meta, "ports"
        self.set_columns(tab, PORT_COLS, "iid")
        tab.sort_col, tab.sort_desc = "ip", False
        self.show_view(tab, "table")
        self.render_table(tab)
        self.update_counter(tab)
        tab.detail.configure(text="Select a port for details. Amber = risky when reachable on a LAN. "
                                   "Double-click a row to ping that host. Closed and filtered ports are not listed.")

    def fill_aps(self, tab, aps, info):
        # hotspots first (so they jump out right after the scan instead of hiding below weaker fixed APs),
        # strongest signal first within each group - engine already sorts this way, but re-apply defensively
        aps = sorted(aps, key=lambda a: (0 if (a.get("hot") or "-") != "-" else 1, -(a.get("sig") or 0)))
        tab.aps, tab.kind, tab.ap_heard = aps, "aps", info.get("heard", len(aps))
        self.set_columns(tab, AP_COLS, "iid")
        tab.sort_col, tab.sort_desc = None, True   # None = keep the hotspots-first order until a column is clicked
        self.show_view(tab, "table")
        self.render_table(tab)
        self.update_counter(tab)
        n_hot = sum(1 for a in aps if (a.get("hot") or "-") != "-")
        tab.detail.configure(
            text=(f"{n_hot} hotspot(s) pinned to the top (pink rows). " if n_hot else "") +
                 "Select a network for details. Red/white = encrypted, orange = weak, amber = OPEN.")

    def fill_bt(self, tab, devs, info):
        tab.bts, tab.kind = devs, "bt"
        self.set_columns(tab, BT_COLS, "address")
        # None = keep the engine's order (trackers first, then nearest first) until a column is clicked
        tab.sort_col, tab.sort_desc = None, True
        self.show_view(tab, "table")
        self.render_table(tab)
        self.update_counter(tab)
        n_tr = sum(1 for d in devs if d.get("tracker"))
        near = ns.nearby_computers(devs)["text"]
        tab.detail.configure(text=(near + "\n" if near else "") +
                             (f"{n_tr} item tracker(s) pinned to the top - red dot = away from its owner. "
                                   if n_tr else "") +
                             "Select a device for details. Passive scan only - nothing is connected to. "
                             "Grey dot = no name or known maker (often a randomised address).")

    def fill_ifaces(self, tab, ifaces):
        tab.ifaces, tab.kind = ifaces, "ifaces"
        self.set_columns(tab, IFACE_COLS, "name")
        tab.sort_col, tab.sort_desc = "name", False
        self.show_view(tab, "table")
        self.render_table(tab)
        self.update_counter(tab)
        tab.detail.configure(text="Select an interface for details. Every adapter on this machine - physical, "
                                   "virtual, VPN and loopback. A DOWN interface has no address.")

    def fill_topo(self, tab, devs, info):
        # the "rows" message _do_scan() already sent (processed just before this one - same queue, FIFO)
        # has already run fill_table(), which sets tab.devs/tab.kind and switches the view to "table";
        # this message's whole job is to switch it on to "topo" instead and actually draw the map - the
        # table underneath stays fully populated, so flipping back to it needs no re-scan either.
        tab.topo_info = info
        self.show_view(tab, "topo")
        self.draw_topology(tab, devs, info)
        tab.topo_detail.configure(text=f"{len(devs)} device(s). Click a node for its details.")

    def draw_topology(self, tab, devs, info):
        """Hub-and-spoke picture: the gateway (or, failing that, this machine) in the middle, every
        other device on one or more concentric rings around it with a line back to the hub. Rings
        (not one crowded circle) keep large networks legible - each ring simply holds more devices
        than the last, since its circumference is bigger - and node color is node_color(d), the exact
        same classification the device table already colors its rows by."""
        cv = tab.topo
        cv.delete("all")
        tab.topo_nodes = []
        w, h = cv.winfo_width(), cv.winfo_height()
        if not w or w < 80:
            w = 760
        if not h or h < 80:
            h = 480
        cx, cy = w // 2, h // 2
        gw_ip, me_ip = info.get("gateway") or "", info.get("ip") or ""
        center_ip = gw_ip or me_ip
        center_dev = next((d for d in devs if d.get("ip") == center_ip), None)
        others = [d for d in devs if d is not center_dev]
        rings, cap, i = [], 9, 0
        while i < len(others):
            take = min(cap, len(others) - i)
            rings.append(others[i:i + take])
            i += take
            cap += 6
        base_r, step_r = min(w, h) * 0.17 + 40, min(w, h) * 0.15 + 46
        node_r = 11
        positions = []
        for ring_i, ring in enumerate(rings):
            r = base_r + ring_i * step_r
            n = len(ring)
            for j, d in enumerate(ring):
                ang = math.radians(-90 + j * (360.0 / n))
                positions.append((d, cx + r * math.cos(ang), cy + r * math.sin(ang)))
        # lines first, so every node is drawn on top of its own line rather than the line on top of it
        for _d, x, y in positions:
            cv.create_line(cx, cy, x, y, fill=DRED, width=1)
        for d, x, y in positions:
            col = node_color(d)
            cv.create_oval(x - node_r, y - node_r, x + node_r, y + node_r, fill=col, outline=BG, width=2)
            cv.create_text(x, y + node_r + 11, text=d.get("ip", "-"), fill=col, font=(FONT, 9))
            extra = d.get("name") or d.get("label") or ""
            if extra:
                cv.create_text(x, y + node_r + 24, text=extra[:22], fill=DRED, font=(FONT, 8))
            tab.topo_nodes.append({"dev": d, "x": x, "y": y, "r": node_r + 6})
        # hub last, so it sits on top of every line and reads as the one clear anchor of the whole map
        hub_r = 18
        hub_kind = "GATEWAY" if gw_ip else ("YOU" if me_ip else "HUB")
        hub_col = node_color(center_dev) if center_dev else WHITE
        hub_label = center_dev.get("ip") if center_dev else (center_ip or "-")
        cv.create_oval(cx - hub_r, cy - hub_r, cx + hub_r, cy + hub_r, fill=hub_col, outline=WHITE, width=2)
        cv.create_text(cx, cy - hub_r - 11, text=hub_kind, fill=WHITE, font=(FONT, 9, "bold"))
        cv.create_text(cx, cy + hub_r + 11, text=hub_label, fill=hub_col, font=(FONT, 9))
        tab.topo_nodes.append({"dev": center_dev, "x": cx, "y": cy, "r": hub_r + 6})
        bbox = cv.bbox("all")
        if bbox:
            pad = 40
            cv.configure(scrollregion=(bbox[0] - pad, bbox[1] - pad, bbox[2] + pad, bbox[3] + pad))

    def on_topo_click(self, tab, e):
        best, best_d2 = None, None
        for node in tab.topo_nodes:
            dx, dy = e.x - node["x"], e.y - node["y"]
            d2 = dx * dx + dy * dy
            if d2 <= node["r"] * node["r"] and (best_d2 is None or d2 < best_d2):
                best, best_d2 = node, d2
        if best is None or best["dev"] is None:
            return
        tab.topo_detail.configure(text=self.device_detail_text(best["dev"]))

    def kpi_values(self, tab):
        """The four headline tiles for whatever this tab shows: [(title, value, unit, red?), ...].
        Mockup order is kept for every kind - a count, the at-risk count (the red tile), what is new or
        notable, and how long the run took - so the eye always finds the same thing in the same place."""
        if tab.running:
            secs, unit = str(int(time.time() - tab.t0)), "s"
        elif tab.last_secs is not None:
            secs, unit = f"{tab.last_secs:.1f}", "s"
        else:
            secs, unit = "—", ""
        timing = ("SCAN TIME", secs, unit, False)
        if tab.view == "camera" and tab.cam:
            c = tab.cam
            return [("CAMERA", c.get("ip", "-"), "", False),
                    ("CONTROL", "W A S D" if c.get("ptz") else "Fixed", "", False),
                    ("PICTURE", "Live" if tab.cam_has_img else "Off", "", not tab.cam_has_img),
                    ("PROFILE", (c.get("name") or c.get("token") or "-")[:12], "", False)]
        if tab.tool == "packet":
            return self._pkt_kpis(tab, timing)
        if tab.tool == "server":
            return self._srv_kpis(tab, timing)
        if tab.tool == "vuln":
            return self._vuln_kpis(tab, timing)
        if tab.tool == "subnet":
            return self._subnet_kpis(tab, timing)
        if tab.tool == "dns":
            return self._dns_kpis(tab, timing)
        if tab.tool == "web":
            return self._web_kpis(tab, timing)
        if tab.tool == "report":
            return self._report_kpis(tab, timing)
        kind = tab.kind
        if kind == "ports":
            rows = tab.pres
            return [("OPEN PORTS", str(len(rows)), "", False),
                    ("WARNINGS", str(sum(1 for r in rows if r.get("note"))), "", True),
                    ("HOSTS", str(len({r.get("ip") for r in rows})), "", False), timing]
        if kind == "aps":
            aps = tab.aps
            sig = [a.get("sig") for a in aps if isinstance(a.get("sig"), (int, float))]
            return [("NETWORKS", str(len(aps)), "", False),
                    ("AT RISK", str(sum(1 for a in aps if a.get("risk") in ("OPEN", "WEAK"))), "", True),
                    ("STRONGEST", (f"{max(sig)}" if sig else "—"), ("%" if sig else ""), False), timing]
        if kind == "apgroups":
            g = tab.apgroups
            return [("ACCESS POINTS", str(len(g)), "", False),
                    ("AT RISK", str(sum(1 for x in g if str(x.get("security") or "").upper().startswith(
                        ("OPEN", "WEP")))), "", True),
                    ("ON YOUR LAN", str(sum(1 for x in g if x.get("ip"))), "", False), timing]
        if kind == "bt":
            bts = tab.bts
            return [("DEVICES", str(len(bts)), "", False),
                    ("TRACKERS", str(sum(1 for b in bts if b.get("tracker"))), "", True),
                    ("NAMED", str(sum(1 for b in bts if b.get("name") not in (None, "", "<unnamed>"))), "", False),
                    timing]
        if kind == "ifaces":
            ifs = tab.ifaces
            up = sum(1 for f in ifs if f.get("up"))
            return [("INTERFACES", str(len(ifs)), "", False), ("DOWN", str(len(ifs) - up), "", True),
                    ("WITH IPV4", str(sum(1 for f in ifs if f.get("ipv4") not in (None, "", "-"))), "", False),
                    timing]
        devs = tab.devs
        empty = not devs and not tab.running and tab.last_secs is None
        dash = "—"
        return [("DEVICES", dash if empty else str(len(devs)), "", False),
                ("AT RISK", dash if empty else str(sum(1 for d in devs if d.get("risk") in ("HIGH", "MEDIUM"))),
                 "", True),
                ("NEW", dash if empty else str(sum(1 for d in devs if d.get("is_new"))), "", False), timing]

    def update_kpis(self, tab):
        """Refresh the four stat tiles from `tab` - only ever for the tab on screen."""
        if tab is not self.active_tab:
            return
        try:
            for tile, (title, value, unit, red) in zip(self.kpi, self.kpi_values(tab)):
                # the red accent only lights up when there IS something at risk - a red '0' cries wolf
                tile.set(value, unit, accent=(red and value not in ("0", "—")), title=title)
        except Exception:
            pass

    def update_counter(self, tab, cycle=None, tot=None):
        self.update_kpis(tab)          # the stat tiles track the same data the counter line does
        if tab.kind == "ports":
            rows, m = tab.pres, tab.pmeta
            tab.counter.configure(
                text=f"{len(rows)} OPEN PORTS    {len({r['ip'] for r in rows})} HOSTS WITH OPEN PORTS    "
                     f"{sum(1 for r in rows if r.get('note'))} WARNINGS    |    scanned {m['hosts']} host(s) x "
                     f"{m['ports']} port(s) in {m['secs']:.1f}s (TCP connect)")
            return
        if tab.kind == "bt":
            bts = tab.bts
            named = sum(1 for b in bts if b.get("name") not in (None, "", "<unnamed>"))
            tab.counter.configure(
                text=f"{len(bts)} BLUETOOTH DEVICES    NAMED {named}    VENDOR KNOWN "
                     f"{sum(1 for b in bts if b.get('vendor'))}    RANDOM ADDRESS {sum(1 for b in bts if b.get('mac_random'))}")
            return
        if tab.kind == "ifaces":
            ifaces = tab.ifaces
            up = sum(1 for f in ifaces if f.get("up"))
            v4 = sum(1 for f in ifaces if f.get("ipv4") not in (None, "", "-"))
            v6 = sum(1 for f in ifaces if f.get("ipv6") not in (None, "", "-"))
            tab.counter.configure(
                text=f"{len(ifaces)} INTERFACES    UP {up}    DOWN {len(ifaces) - up}    "
                     f"WITH IPV4 {v4}    WITH IPV6 {v6}")
            return
        if tab.kind == "apgroups":
            g = tab.apgroups
            onlan = sum(1 for x in g if x.get("ip"))
            nearest = next((x.get("dist_range") or ns.fmt_distance(x.get("dist_m")) for x in g
                            if x.get("dist_m") is not None), "-")
            tab.counter.configure(
                text=f"{len(g)} ACCESS POINTS    ON YOUR NETWORK {onlan}    "
                     f"RADIOS {sum(x.get('radios', 1) for x in g)}    "
                     f"HOTSPOTS {sum(1 for x in g if x.get('hot') not in (None, '', '-'))}    "
                     f"NEAREST {nearest}")
            return
        if tab.kind == "aps":
            aps = tab.aps
            band = lambda b: sum(1 for a in aps if a.get("band") == b)
            rows = self.cur_rows(tab)
            tab.counter.configure(
                text=(f"{len(rows)} of {len(aps)} shown    " if len(rows) != len(aps) else f"{len(aps)} ")
                     + f"ACCESS POINTS    {len({a['ssid'] for a in aps})} NETWORKS    "
                     f"OPEN {sum(1 for a in aps if a['risk'] == 'OPEN')}    WEAK {sum(1 for a in aps if a['risk'] == 'WEAK')}"
                     f"    2.4 GHz {band('2.4 GHz')}    5 GHz {band('5 GHz')}    6 GHz {band('6 GHz')}"
                     + (f"    5/6 GHz(?) {band('5/6 GHz (?)')}" if band("5/6 GHz (?)") else "")
                     + f"    HOTSPOTS {sum(1 for a in aps if a.get('hot') not in (None, '', '-'))}"
                     + (f"    (of {tab.ap_heard} heard)" if tab.ap_heard != len(aps) else ""))
            return
        on = sum(1 for d in tab.devs if d.get("state") == "ONLINE")
        off = sum(1 for d in tab.devs if d.get("state") == "OFFLINE")
        nop = sum(1 for d in tab.devs if d.get("state") == "NO PING")
        text = f"ONLINE {on}    OFFLINE {off}    NO PING {nop}    TOTAL {len(tab.devs)}"
        if cycle:
            sent, recv = tot
            loss = 100.0 * (sent - recv) / sent if sent else 0.0
            text += (f"    |    LIVE  cycle {cycle}   packets sent {sent}  received {recv}  loss {loss:.0f}%"
                     f"   updated {datetime.datetime.now():%H:%M:%S}")
        tab.counter.configure(text=text)

    def apply_live(self, tab, updates, cycle, tot):
        if tab.kind != "devs":
            return
        by_ip = {d["ip"]: d for d in tab.devs}
        for ip, u in updates.items():
            d = by_ip.get(ip)
            if not d:
                continue
            d.update(u)
            if tab.tree.exists(ip):
                for col in ("status", "ms", "pkts", "jitter", "loss", "quality"):
                    # same "  " padding render_table() gives every cell - without it, a device's status/
                    # ms/pkts columns would lose their gap the moment LIVE MONITOR updates them in place,
                    # while every other column (and every column on the row for "your own" IP, which LIVE
                    # never touches) kept it - a small, real inconsistency this closes.
                    if col in d:
                        tab.tree.set(ip, col, f"  {d[col]}")
                tab.tree.item(ip, tags=(row_tag(d),))
        self.update_counter(tab, cycle, tot)

    # ---- save -------------------------------------------------------------
    def table_text(self, tab):
        keys = [c[0] for c in tab.cols]
        rows = sorted(self.cur_rows(tab), key=lambda d: self.sort_value(tab, d), reverse=tab.sort_desc)

        def cell(d, k):
            if k == "signal" and "sig" in d:
                return f"{d['sig']}%"
            return str(d.get(k) or "-")[:60]
        widths = [max(len(c[1]), *(len(cell(d, c[0])) for d in rows)) + 2 for c in tab.cols]
        lines = ["".join(c[1].ljust(w) for c, w in zip(tab.cols, widths)), "-" * sum(widths)]
        lines += ["".join(cell(d, k).ljust(w) for k, w in zip(keys, widths)) for d in rows]
        if tab.kind == "ports":
            lines.append(f"\n{len(rows)} open port(s) on {len({d['ip'] for d in rows})} host(s) "
                         f"({tab.pmeta['hosts']} scanned x {tab.pmeta['ports']} ports). "
                         "Closed and filtered ports are not listed.")
        elif tab.kind == "bt":
            lines.append(f"\n{len(rows)} Bluetooth device(s) heard. Passive scan only.")
        elif tab.kind == "ifaces":
            lines.append(f"\n{len(rows)} network interface(s).")
        else:
            lines.append(f"\n{len(rows)} {'device(s)' if tab.kind == 'devs' else 'access point(s)'}.")
        return lines

    def save_txt(self):
        tab = self.active_tab
        if tab.running:
            return
        if tab.view in ("table", "topo") and self.cur_rows(tab):
            body = ns.info_lines(self.info) + [""] + self.table_text(tab)
        else:
            body = tab.console.get("1.0", "end").rstrip().splitlines()
        if not any(l.strip() for l in body):
            messagebox.showinfo("NETSCOUT", "Nothing to save yet - run a tool first.")
            return
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        path = filedialog.asksaveasfilename(defaultextension=".txt", initialfile=f"netscout_{tab.tool}_{stamp}.txt",
                                            filetypes=[("Text file", "*.txt")])
        if not path:
            return
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(f"NetScout report - {datetime.datetime.now():%Y-%m-%d %H:%M:%S} - {socket.gethostname()}\n\n")
                f.write("\n".join(body) + "\n")
            ns.set_permissions(path, private=not self.everyone.get())
            self.set_status(f"SAVED {path} ({'readable by everyone' if self.everyone.get() else 'owner only'})")
        except OSError as e:
            messagebox.showerror("NETSCOUT", f"Could not save the file:\n{e}")

    def _save_structured(self, tab, fmt):
        """Shared body for SAVE CSV / SAVE JSON - same pattern as save_txt() but for structured,
        machine-readable export via ns.save_rows() (real csv/json stdlib writers, so embedded
        commas/quotes in hostnames, vendors, banners etc. round-trip correctly)."""
        if tab.running:
            return
        if tab.view not in ("table", "topo") or not self.cur_rows(tab):
            messagebox.showinfo("NETSCOUT", "Nothing to save yet - run a tool and switch to the table view.")
            return
        rows = sorted(self.cur_rows(tab), key=lambda d: self.sort_value(tab, d), reverse=tab.sort_desc)
        cols = [(c[0], c[1]) for c in tab.cols]
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        path = filedialog.asksaveasfilename(defaultextension=f".{fmt}", initialfile=f"netscout_{tab.tool}_{stamp}.{fmt}",
                                            filetypes=[(f"{fmt.upper()} file", f"*.{fmt}")])
        if not path:
            return
        try:
            ns.save_rows(path, rows, cols, fmt, private=not self.everyone.get())
            self.set_status(f"SAVED {path} ({'readable by everyone' if self.everyone.get() else 'owner only'})")
        except OSError as e:
            messagebox.showerror("NETSCOUT", f"Could not save the file:\n{e}")

    def save_csv(self):
        self._save_structured(self.active_tab, "csv")

    def save_json(self):
        self._save_structured(self.active_tab, "json")

    def compare_scans(self):
        """COMPARE button: diff the two most recent saved scan snapshots (every DEVICE/NETWORK SCAN
        saves one automatically - see _do_scan()) and show what changed in the console view."""
        tab = self.active_tab
        if tab.running:
            return
        snaps = ns.list_snapshots()
        if len(snaps) < 2:
            messagebox.showinfo("NETSCOUT", "Need at least two saved scans to compare. Every DEVICE SCAN or "
                                "NETWORK SCAN saves one automatically - just run one more and try again.")
            return
        newer, older = snaps[0], snaps[1]
        diff = ns.diff_snapshots(ns.load_snapshot(older["stamp"]), ns.load_snapshot(newer["stamp"]))
        self.show_view(tab, "console")
        tab.console.configure(state="normal")
        tab.console.delete("1.0", "end")
        tab.console.configure(state="disabled")
        for line in ns.diff_lines(diff, older.get("label") or older["stamp"], newer.get("label") or newer["stamp"]):
            tag = "bad" if line.strip()[:1] in ("+", "-", "~") else ("big" if line.startswith("COMPARISON") else "key")
            self.write(tab, line, tag)
        self.set_status(f"COMPARED {older['stamp']} -> {newer['stamp']}")

    def show_row_menu(self, tab, _event):
        """Right-click (Button-3 on Win/Linux, Button-2 on macOS) context menu for the device table.
        Acts on whatever row is currently selected, same as copy_row() already does, rather than
        hit-testing the click position - simpler, and matches the existing selection-driven pattern."""
        if tab.kind != "devs" or tab.running:
            return
        sel = tab.tree.selection()
        d = next((x for x in self.cur_rows(tab) if sel and x[tab.rid] == sel[0]), None)
        if not d:
            return
        menu = tk.Menu(self, tearoff=0, bg=PANEL, fg=BRIGHT, activebackground="#241017", activeforeground=WHITE)
        menu.add_command(label=f"EDIT NOTE / TAG for {d['ip']}...", command=lambda: self.edit_note_popup(tab, d))
        if d.get("note"):
            menu.add_command(label="CLEAR NOTE / TAG", command=lambda: self.save_note(tab, d, ""))
        menu.add_separator()
        if d.get("approved"):
            menu.add_command(label="REMOVE APPROVAL (alert on this device again)",
                             command=lambda: self.set_approved(tab, d, False))
        else:
            menu.add_command(label="MARK AS APPROVED (stop alerting on this device)",
                             command=lambda: self.set_approved(tab, d, True))
        menu.add_separator()
        # respond to an attack - cut the offending host off, two reversible ways, each credential-gated:
        menu.add_command(label=f"BLOCK {d['ip']} at THIS PC's firewall (during an attack)",
                         command=lambda: self.block_device(tab, d, block=True))
        menu.add_command(label=f"UNBLOCK {d['ip']} at this PC's firewall",
                         command=lambda: self.block_device(tab, d, block=False))
        menu.add_command(label=f"DISCONNECT {d['ip']} (disable its switch port)",
                         command=lambda: self.disconnect_device(tab, d, up=False))
        menu.add_command(label=f"RECONNECT {d['ip']} (re-enable its switch port)",
                         command=lambda: self.disconnect_device(tab, d, up=True))
        menu.add_separator()
        menu.add_command(label="WAKE UP (Wake-on-LAN)", command=lambda: self.power_action("wake", d))
        menu.add_command(label="CHECK IF IN USE", command=lambda: self.power_action("check", d))
        menu.add_command(label="POWER OFF...", command=lambda: self.power_action("off", d))
        menu.add_command(label="RESTART...", command=lambda: self.power_action("restart", d))
        menu.add_command(label="CANCEL A PENDING POWER-OFF", command=lambda: self.power_action("cancel", d))
        menu.add_command(label="POWER ON (server BMC / IPMI)...", command=lambda: self.power_action("on", d))
        menu.add_command(label="HARD POWER CYCLE (IPMI)...", command=lambda: self.power_action("cycle", d))
        menu.add_separator()
        # lasting power POLICY (needs WinRM/SSH on the target) - each shows the exact command before it runs
        menu.add_command(label="POLICY: sleep when idle...", command=lambda: self.policy_action("sleep", d))
        menu.add_command(label="POLICY: never sleep (stay awake)...",
                         command=lambda: self.policy_action("wake_sleep_off", d))
        menu.add_command(label="POLICY: shut down after hours...",
                         command=lambda: self.policy_action("schedule_off", d))
        menu.add_command(label="POLICY: cancel the nightly shutdown...",
                         command=lambda: self.policy_action("cancel_off", d))
        menu.add_command(label="POLICY: allow IT management (root-cause fix)...",
                         command=lambda: self.policy_action("allow_mgmt", d))
        menu.add_command(label="POLICY: remove IT-management allowance...",
                         command=lambda: self.policy_action("revoke_mgmt", d))
        try:
            menu.tk_popup(_event.x_root, _event.y_root)
        finally:
            menu.grab_release()

    def _locate_ap(self):
        """Arm the hunt for the selected access point, then run the apscan tool - which, seeing a target
        armed, hunts instead of listing. Going through run_tool means STOP ends it like any other run."""
        tab = self.active_tab
        if tab.running:
            return
        if tab.kind != "apgroups":
            messagebox.showinfo("NETSCOUT", "Run ACCESS POINTS first, then select one and press LOCATE.")
            return
        sel = tab.tree.selection()
        if not sel or ":" not in sel[0]:
            messagebox.showinfo("NETSCOUT", "Select an access point in the list first, then press LOCATE.")
            return
        self._pending_hunt = sel[0]
        self.run_tool()

    def _firewall_toggle(self, on):
        """Turn the OS firewall on or off, from the FIREWALL tool's buttons. Confirms first, runs the
        OS command off the main thread, and reports the result into the active tab."""
        verb = "ON" if on else "OFF"
        if not messagebox.askyesno("NETSCOUT - firewall",
                                   f"Turn the operating system firewall {verb}?\n\n"
                                   + ("This blocks unsolicited inbound connections to this machine."
                                      if on else "This REMOVES that protection - only do it deliberately.")
                                   + "\n\nIt needs administrator rights."):
            return
        tab = self.active_tab
        self.set_status(f"Turning the firewall {verb}...")

        def work():
            ok, msg = ns.firewall_set(on)
            tab.q.put(("notice", msg, "ok" if ok else "bad"))
        threading.Thread(target=work, daemon=True).start()

    def _macpriv_apply(self):
        """Apply the generated random MAC to the named interface. Confirms, warns about the link drop,
        and runs the OS command off the main thread."""
        mac = getattr(self, "_macpriv_new", "") or ns.random_mac()
        iface = self.mac_iface_var.get().strip()
        if not iface:
            messagebox.showinfo("NETSCOUT", "Type the interface name to change (e.g. eth0, wlan0, en0) "
                                "into the INTERFACE box first. RUN lists the active ones.")
            return
        if not messagebox.askyesno("NETSCOUT - change MAC",
                                   f"Set {iface} to the random address {mac}?\n\n"
                                   "The network connection on that interface will drop for a moment and "
                                   "reconnect. This needs administrator rights, and some adapters (most "
                                   "Wi-Fi) refuse a MAC change.\n\nContinue?"):
            return
        tab = self.active_tab
        self.set_status(f"Changing the MAC of {iface}...")

        def work():
            ok, msg = ns.set_mac(iface, mac)
            tab.q.put(("notice", msg, "ok" if ok else "bad"))
        threading.Thread(target=work, daemon=True).start()

    # ---- IP CAMERA (ONVIF, authenticated) ----------------------------------------------------------------
    def w_camera(self, tab, o):
        """Log in to a camera you administer with its OWN ONVIF login, then hand it to the live view. The
        camera checks that login on every frame and every move - without it, nothing here gets in."""
        tab.log("IP CAMERA\n", "big")
        ip, user, pw = self.cam_ip_var.get().strip(), self.cam_user_var.get().strip(), self.cam_pass_var.get()
        if not ip or not user:
            tab.log("Enter the camera's address and its ONVIF user name and password (the camera's own login - "
                    "set in its web page or app, often under Network > ONVIF).", "bad")
            return
        tab.log(f"Logging in to {ip} as {user}...", "dim")
        cam = ns.camera_connect(ip, user, pw)
        if not cam["ok"]:
            tab.log(cam["error"], "bad")
            return
        tab.log(f"Connected to {cam.get('name') or ip}. " +
                ("It can pan / tilt / zoom: W A S D to move, E / Q to zoom." if cam["ptz"]
                 else "It's a fixed camera (no pan / tilt / zoom)."), "ok")
        if cam.get("stream_uri"):
            tab.log(f"Full-quality video (RTSP): {cam['stream_uri']} - open it in VLC for smooth video.", "dim")
        has_img = ns.ensure_pillow(lambda m: tab.log("> " + m, "dim"))
        tab.q.put(("camera", cam, has_img))

    CAM_FRAME_MS = 350          # ~3 pictures a second: live enough to steer by, light on the camera

    def camera_open(self, tab, cam, has_img):
        self.camera_close(tab)
        tab.cam, tab.cam_has_img, tab.cam_busy = cam, has_img, False
        self.show_view(tab, "camera")
        keys = "W / A / S / D move, E / Q zoom (click the picture first if a text box has the keyboard)" \
            if cam.get("ptz") else "fixed camera - no movement"
        tab.cam_status.configure(text=f"{cam.get('name') or cam.get('ip')}  |  {keys}" +
                                 ("" if has_img else "  |  picture needs the Pillow package - control still works")
                                 + (f"  |  RTSP: {cam['stream_uri']}" if cam.get("stream_uri") else ""))
        tab.cam_img.configure(image="", text="Connecting to the camera's picture..." if has_img else
                              "No picture (Pillow not available) - W/A/S/D still steer the camera.")
        tab.cam_img.bind("<Button-1>", lambda e: tab.cam_img.focus_set())
        self.update_kpis(tab)
        self.focus_set()
        self._camera_poll(tab)

    def _camera_poll(self, tab):
        if tab.cam is None:
            return
        if tab.cam_has_img and not tab.cam_busy and tab is self.active_tab and tab.view == "camera":
            tab.cam_busy = True
            cam = tab.cam

            def work():
                jpg, err = ns.camera_snapshot(cam)
                tab.q.put(("camframe", jpg, err))
            threading.Thread(target=work, daemon=True).start()
        tab.cam_after = self.after(self.CAM_FRAME_MS, lambda: self._camera_poll(tab))

    def camera_frame(self, tab, jpg, err):
        tab.cam_busy = False
        if tab.cam is None or tab.view != "camera":
            return
        if err or not jpg:
            tab.cam_img.configure(image="", text=err or "No picture from the camera.")
            tab.cam_imgref = None
            return
        try:
            import io as _io
            from PIL import Image
            im = Image.open(_io.BytesIO(jpg))
            im.load()
            w = max(160, tab.cam_img.winfo_width() or 640)
            h = max(120, tab.cam_img.winfo_height() or 480)
            im.thumbnail((w, h))
            buf = _io.BytesIO()
            im.convert("RGB").save(buf, "PNG")
            photo = tk.PhotoImage(data=buf.getvalue())
            tab.cam_img.configure(image=photo, text="")
            tab.cam_imgref = photo          # Tk drops an image nobody holds a reference to
        except Exception as e:
            tab.cam_img.configure(image="", text=f"Could not show the picture: {e}")

    def camera_close(self, tab):
        """Stop the feed, stop any movement, forget the login."""
        if tab.cam_after:
            try:
                self.after_cancel(tab.cam_after)
            except Exception:
                pass
        tab.cam_after = None
        cam, tab.cam, tab.cam_moving, tab.cam_imgref = tab.cam, None, "", None
        if cam and cam.get("ptz"):
            threading.Thread(target=lambda: ns.camera_stop(cam), daemon=True).start()

    def _cam_target(self, e):
        tab = self.active_tab
        if tab is None or tab.cam is None or tab.view != "camera":
            return None, ""
        if isinstance(self.focus_get(), (tk.Entry, tk.Text)):
            return None, ""          # typing in a box must never move the camera
        key = (getattr(e, "keysym", "") or "").lower()
        return (tab, key) if key in ns.PTZ_KEYS else (None, "")

    def _cam_key(self, e):
        tab, key = self._cam_target(e)
        if not tab:
            return
        if tab.cam_moving == key + "?":           # auto-repeat of a held key: it never really let go
            tab.cam_moving = key
            return
        if tab.cam_moving == key:                 # already moving this way - don't resend 30x a second
            return
        tab.cam_moving = key
        cam, (x, y, z) = tab.cam, ns.PTZ_KEYS[key]

        def work():
            ok, err = ns.camera_move(cam, x, y, z)
            if not ok:
                tab.q.put(("notice", err, "bad"))
        threading.Thread(target=work, daemon=True).start()

    def _cam_key_up(self, e):
        """Stop moving on release. A held key auto-repeats as release+press pairs (X11, some Windows
        setups), so the stop waits 60 ms: if the same key is pressed again in that time it was auto-repeat
        and the camera keeps moving smoothly instead of stuttering."""
        tab, key = self._cam_target(e)
        if not tab or tab.cam_moving != key:
            return
        tab.cam_moving = key + "?"

        def settle():
            if tab.cam_moving == key + "?" and tab.cam is not None:
                tab.cam_moving = ""
                cam = tab.cam
                threading.Thread(target=lambda: ns.camera_stop(cam), daemon=True).start()
        self.after(60, settle)

    def _own_lan_mac(self, info):
        """This computer's MAC on the LAN - the interface whose IPv4 is our own address. Used to keep our
        own switch port UP during a lockdown so we don't cut ourselves off."""
        me = (info or {}).get("ip")
        for f in (ns.list_interfaces() or []):
            v4 = f.get("ipv4") or ""
            if me and (v4 == me or me in [x.strip() for x in re.split(r"[,\s]+", v4) if x]):
                return f.get("mac") or ""
        return ""

    def emergency_lockdown(self, lift):
        """Serious-incident containment: with a managed switch, disable (or re-enable) every device port at
        once so the whole LAN drops off the network - phones, tablets, IoT included - because it removes
        their network access, not power. Credential-gated (switch SNMP write), reversible, and it keeps this
        machine's own port + the uplink up so control is never lost."""
        tab = self.active_tab
        if tab.running:
            return
        info = self.info or ns.net_info() or {}
        switch = simpledialog.askstring(
            "NETSCOUT - emergency lockdown", "IP of the managed switch to lock down\n(usually your gateway):",
            initialvalue=info.get("gateway", ""), parent=self)
        if not switch:
            return
        if not lift and not messagebox.askyesno(
                "NETSCOUT - EMERGENCY LOCKDOWN",
                f"Disable EVERY device port on the switch {switch} right now?\n\n"
                "This cuts ALL devices off the network at once - phones, tablets, computers, cameras, "
                "everything - to contain a serious cyber incident. Your own port and the uplink stay up.\n\n"
                "Nothing is powered off; devices lose network access until you LIFT the lockdown. This needs "
                "the switch's SNMP WRITE community and is logged.\n\nProceed?"):
            return
        write = simpledialog.askstring(
            "NETSCOUT", f"SNMP WRITE community for the switch {switch}\n(the credential that authorises this):",
            initialvalue="private", parent=self, show="*")
        if not write:
            return
        admin_mac = self._own_lan_mac(info)
        gw = info.get("gateway", "")
        keep_macs = []
        try:
            gw_mac = ns.arp_table().get(gw, "") if gw else ""
        except Exception:
            gw_mac = ""
        if gw_mac:
            keep_macs.append(gw_mac)
        self.set_status(("Lifting lockdown on " if lift else "Locking down ") + f"{switch}...")

        def work():
            res = ns.switch_lockdown(switch, write, admin_mac=admin_mac, keep_macs=keep_macs, lift=lift,
                                     log=lambda m: tab.q.put(("log", "> " + m, "dim")))
            for line in ns.lockdown_lines(res, switch):
                tab.q.put(("log", line, "ok" if res.get("ok") else "bad"))
            msg = (ns.lockdown_lines(res, switch)[0] if res.get("error") and not res.get("changed")
                   else f"{'Lifted lockdown' if lift else 'LOCKDOWN ACTIVE'} on {switch}: "
                        f"{len(res.get('changed', []))} port(s) {'re-enabled' if lift else 'disabled'}, "
                        f"{len(res.get('kept', []))} kept online.")
            tab.q.put(("notice", msg, "ok" if res.get("ok") else "bad"))
        threading.Thread(target=work, daemon=True).start()

    def block_device(self, tab, d, block):
        """Shut one host out of THIS computer (or let it back in) with a rule in the OS's own firewall.

        The honest 'respond to an attack' move that needs no special gear: it defends the machine NetScout
        runs on, needs admin/root on THIS machine (the OS checks that), is reversible, and touches no other
        device. It never powers anything off - blocking an attacker at your own door is the defensive act.
        """
        ip = d.get("ip")
        if not ip:
            messagebox.showinfo("NETSCOUT", "This row has no IP address to block.")
            return
        if block and not messagebox.askyesno(
                "NETSCOUT - block at firewall",
                f"Block {ip} ({d.get('label', '')}) at THIS computer's firewall?\n\n"
                "It won't be able to reach this machine until you UNBLOCK it. No other device is affected, "
                "and nothing is powered off.\n\nThis changes this PC's own firewall and needs admin / root here."):
            return
        self.set_status(f"{'Blocking' if block else 'Unblocking'} {ip} at this computer's firewall...")

        def work():
            ok, msg = ns.firewall_block_host(ip, block=block)
            tab.q.put(("notice", msg, "ok" if ok else "bad"))
        threading.Thread(target=work, daemon=True).start()

    def disconnect_device(self, tab, d, up):
        """Kick a device off the network - or let it back on - by disabling the switch port it is on.

        This is the admin way to isolate a suspicious machine: precise (one physical port), reversible
        (RECONNECT brings it straight back), and auditable. It works ONLY against a managed switch you
        hold SNMP write credentials for - which is exactly why it is safe to put in everyone's hands: the
        write community is the gate, and someone without it changes nothing. NetScout never forges
        traffic or attacks a device directly; this acts through infrastructure you administer.
        """
        if not d.get("mac"):
            messagebox.showinfo("NETSCOUT", "This device has no known MAC address, so its switch port "
                                "can't be located. A device has to be seen with a hardware address first.")
            return
        info = ns.net_info() or {}
        switch = simpledialog.askstring(
            "NETSCOUT", "IP of the managed switch this device is on\n(usually your gateway):",
            initialvalue=info.get("gateway", ""), parent=self)
        if not switch:
            return
        action = "RE-ENABLE" if up else "DISABLE"
        if not up and not messagebox.askyesno(
                "NETSCOUT - confirm disconnect",
                f"{action} the switch port that {d['ip']} ({d.get('label', '')}) is plugged into?\n\n"
                "That device will lose all network access until you RECONNECT it.\n\n"
                "This needs SNMP WRITE access to the switch and is logged. Continue?"):
            return
        write = simpledialog.askstring(
            "NETSCOUT", f"SNMP WRITE community for the switch {switch}\n"
            "(this is the credential that authorises the change - usually 'private'):",
            initialvalue="private", parent=self, show="*")
        if not write:
            return
        self.set_status(f"{'Re-enabling' if up else 'Disabling'} the port for {d['ip']} on {switch}...")

        def work():
            ok, msg = ns.set_device_port(switch, d["mac"], up=up, write_community=write)
            tab.q.put(("notice", msg, "ok" if ok else "bad"))
        threading.Thread(target=work, daemon=True).start()

    def edit_note_popup(self, tab, d):
        if not d.get("mac"):
            messagebox.showinfo("NETSCOUT", "This device has no known hardware (MAC) address yet, so a "
                                "note can't be attached reliably - notes are saved by MAC so they still "
                                "find the same device after its IP changes.")
            return
        text = simpledialog.askstring("NETSCOUT", f"Note / tag for {d['ip']}  ({d.get('label', '')}):",
                                      initialvalue=d.get("note", ""), parent=self)
        if text is not None:
            self.save_note(tab, d, text)

    def save_note(self, tab, d, text):
        try:
            ns.set_note(d["mac"], text)
        except OSError as e:
            messagebox.showerror("NETSCOUT", f"Could not save the note:\n{e}")
            return
        d["note"] = (text or "").strip()
        if tab.tree.exists(d[tab.rid]):
            tab.tree.set(d[tab.rid], "note", f"  {d['note'] or '-'}")
        self.set_status(f"NOTE SAVED for {d['ip']}" if d["note"] else f"NOTE CLEARED for {d['ip']}")

    def set_approved(self, tab, d, approved):
        """Mark a device as expected on this network (or stop doing so). Mirrors save_note(): same
        by-MAC store, same write-then-update-the-visible-cell pattern, same refusal to guess when
        there's no MAC to key it on."""
        if not d.get("mac"):
            messagebox.showinfo("NETSCOUT", "This device has no known hardware (MAC) address yet, so it "
                                "can't be approved reliably - approvals are saved by MAC so they still "
                                "apply to the same device after its IP changes.")
            return
        try:
            ns.set_approved(d["mac"], approved)
        except OSError as e:
            messagebox.showerror("NETSCOUT", f"Could not save the approval:\n{e}")
            return
        d["approved"] = bool(approved)
        d["ok_disp"] = "YES" if approved else ""
        if tab.tree.exists(d[tab.rid]):
            tab.tree.set(d[tab.rid], "ok_disp", f"  {d['ok_disp'] or '-'}")
        self.set_status(f"APPROVED {d['ip']} - BACKGROUND WATCH will no longer alert on it" if approved
                        else f"APPROVAL REMOVED for {d['ip']}")

    def toggle_fullscreen(self, _event=None):
        self.fullscreen = not self.fullscreen
        try:
            self.attributes("-fullscreen", self.fullscreen)
        except tk.TclError:
            pass  # some window managers/platforms reject this attribute - leave the window as it was
        self._sync_fullscreen_btn()

    def exit_fullscreen(self, _event=None):
        if self.fullscreen:
            self.fullscreen = False
            try:
                self.attributes("-fullscreen", False)
            except tk.TclError:
                pass
            self._sync_fullscreen_btn()

    def _sync_fullscreen_btn(self):
        """Keep the View menu's entry honest about what it will do next, whichever way the state was
        changed - the menu, F11, or Escape all land here."""
        self.full_label = "Windowed" if self.fullscreen else "Fullscreen"
        menu = getattr(self, "view_menu", None)
        if menu is not None:
            try:
                menu.entryconfigure(menu.index("end"), label=self.full_label)
            except Exception:
                pass

    def on_close(self):
        for tab in self.tabs:
            tab.cancel.set()
            self.camera_close(tab)
            p = tab.proc
            if p and p.poll() is None:
                try:
                    p.terminate()
                except Exception:
                    pass
        self.destroy()


