def selftest():
    """Used by the build scripts right after building, to PROVE the packaged program starts on its own.
    The build script runs NetScout.exe --selftest with Python stripped out of PATH/PYTHONHOME, so if the
    .exe secretly leaned on an installed Python (e.g. for Tcl/Tk) this fails on the build machine itself,
    instead of later on someone else's laptop. Exit code 0 = OK; any other = broken build."""
    import sys as _s
    try:
        import tkinter as _tk
        r = _tk.Tk()
        r.withdraw()
        r.update_idletasks()
        r.destroy()
        _s.exit(0)
    except SystemExit:
        raise
    except Exception:
        _s.exit(3)


if __name__ == "__main__":
    import sys as _sys
    if "--selftest" in _sys.argv:
        selftest()
    # Dual GUI/CLI binary: NetScout launches the GUI, but `NetScout wreport ...` (or any engine subcommand)
    # runs the headless CLI instead - so a scheduled weekly report works from the built app with no Python.
    _CLI = {"info", "scan", "ping", "bluetooth", "nearby", "ports", "wifi", "interfaces", "wreport"}
    if len(_sys.argv) > 1 and _sys.argv[1] in _CLI:
        ns.main()
        _sys.exit(0)
    App().mainloop()
